#!/usr/bin/env python3
"""A custom context manager that times the execution of a code block."""

class Timer:
    """A context manager that measures the time taken to execute a block of code."""
    def __enter__(self):
        self.start_time = time.time()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.end_time = time.time()
        self.duration = self.end_time - self.start_time
        print(f"Execution time: {self.duration:.4f} seconds")

if __name__ == '__main__':
    import time
    with Timer() as timer:
        time.sleep(1)
    print(f"Total time: {timer.duration:.4f} seconds")

#!/usr/bin/env python3
"""A context manager to temporarily change the current working directory."""

import os

class TemporaryDirectory:
    """A context manager that temporarily changes the current working directory."""
    def __init__(self, new_dir):
        self.new_dir = new_dir
        self.original_dir = os.getcwd()

    def __enter__(self):
        os.chdir(self.new_dir)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        os.chdir(self.original_dir)

if __name__ == '__main__':
    with TemporaryDirectory('/tmp') as cd:
        print(f"Current directory: {os.getcwd()}")
    print(f"Back to original directory: {os.getcwd()}")

#!/usr/bin/env python3
"""A context manager that logs messages to a file and prints them to the console."""

class Logger:
    """A context manager that logs messages to a file and prints them to the console."""
    def __init__(self, log_file):
        self.log_file = log_file

    def __enter__(self):
        self.file = open(self.log_file, 'a')
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.file.close()

    def log(self, message):
        self.file.write(f'{message}\n')
        print(message)

if __name__ == '__main__':
    with Logger('app.log') as logger:
        logger.log('Application started')
        logger.log('Processing data...')
        logger.log('Application finished')

