class UnionFind:
    """Union-Find (Disjoint Set Union) data structure."

    Attributes:
        parent (list): Tracks the parent of each element.
        rank (list): Tracks the rank (size) of each set for union by rank.
    """

    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [1] * size

    def find(self, x):
        """Find the root of the set containing x with path compression."""
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        """Union by rank, merging the smaller set into the larger one."""
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            return

        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        else:
            self.parent[root_y] = root_x
            if self.rank[root_x] == self.rank[root_y]:
                self.rank[root_x] += 1

    def get_components(self):
        """Return the number of connected components."""
        return len({self.find(i) for i in range(len(self.parent))})

# Example usage
if __name__ == "__main__":
    uf = UnionFind(5)
    uf.union(0, 1)
    uf.union(2, 3)
    print(f"Number of components: {uf.get_components()}")

class UnionFind:
    """Union-Find (Disjoint Set Union) implementation with path compression."

    Attributes:
        parent: List of parent pointers.
    """

    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_y] = root_x

    def are_connected(self, x, y):
        return self.find(x) == self.find(y)

