# This script performs a depth-first search on a graph and prints visited nodes in order.

def dfs_path(graph, start, end):
    def _dfs(node, path):
        if node == end:
            return path + [node]
        for neighbor in graph[node]:
            if neighbor not in path:
                result = _dfs(neighbor, path + [node])
                if result:
                    return result
        return None
    return _dfs(start, [])

