class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def merge(self, other):
        merged = LinkedList()
        current1 = self.head
        current2 = other.head
        while current1 and current2:
            if current1.data <= current2.data:
                merged.append(current1.data)
                current1 = current1.next
            else:
                merged.append(current2.data)
                current2 = current2.next
        while current1:
            merged.append(current1.data)
            current1 = current1.next
        while current2:
            merged.append(current2.data)
            current2 = current2.next
        return merged

    def print_list(self):
        current = self.head
        while current:
            print(current.data, end=' -> ')
            current = current.next
        print('None')

if __name__ == '__main__':
