'''
Fibonacci Generator
This script generates the first 10 Fibonacci numbers using a generator function.
'''

def fibonacci_generator(n):
    '''Yields the first n Fibonacci numbers'''
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

if __name__ == "__main__":
    for num in fibonacci_generator(10):
        print(num)

'''
Line Reader Generator
This script reads a large file line by line using a generator to avoid loading the whole file into memory.
'''

def read_large_file(file_path):
    '''Generator that reads a file line by line'''
    with open(file_path, 'r') as file:
        for line in file:
            yield line.strip()

if __name__ == "__main__":
    for line in read_large_file('large_file.txt'):
        print(line)

