'''
Demonstration of Dijkstra's algorithm on a weighted graph.
'''
import heapq

def dijkstra(graph, start):
    """Find the shortest path from start to all other nodes using Dijkstra's algorithm.

    Args:
        graph: Dictionary of adjacency lists.
        start: Starting node.

    Returns:
        Dictionary of shortest distances from start to each node.
    """
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        dist, node = heapq.heappop(heap)
        if dist > distances[node]:
            continue
        for neighbor, weight in graph[node].items():
            if distances[neighbor] > dist + weight:
                distances[neighbor] = dist + weight
                heapq.heappush(heap, (dist + weight, neighbor))

    return distances

if __name__ == "__main__":
