'''
Solve the 'Number of Islands' problem using Union-Find
'''

def count_islands(grid):
    rows = len(grid)
    cols = len(grid[0])
    uf = UnionFind(rows * cols)
    directions = [(0,1), (1,0)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                        uf.union(r * cols + c, nr * cols + nc)
    components = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                components.add(uf.find(r * cols + c))
    return len(components)

