'''
Check if a string contains a palindrome substring of length k using sliding window technique.
'''
def is_palindrome_substring(s, k):
    """Return True if there is a palindrome substring of length k, else False."""
    for i in range(len(s) - k + 1):
        substring = s[i:i + k]
        if substring == substring[::-1]:
            return True
    return False

