# A custom iterator for a linked list

class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

class LinkedList:
    def __init__(self, values=None):
        self.head = None
        if values:
            for value in reversed(values):
                self.head = Node(value, self.head)

    def __iter__(self):
        current = self.head
        while current:
            yield current.value
            current = current.next

# Example usage
ll = LinkedList([1, 2, 3])
for num in ll:
    print(num)

