'''Topological sort implementation using Kahn's algorithm.'''

def topological_sort(graph):
    '''Return a topological order of the graph using Kahn's algorithm.'''
    in_degree = {node: 0 for node in graph}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = [node for node in in_degree if in_degree[node] == 0]
    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != len(graph):
        raise ValueError("Graph has a cycle")
    return result

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': []
    }
    print(topological_sort(graph))

'''Topological sort with cycle detection using DFS.'''

def topological_sort_dfs(graph):
    '''Return topological order using DFS. Raises ValueError for cycles.'''
    visited = set()
    result = []
    stack = []

    def dfs(node):
        if node in visited:
            if node in stack:
                raise ValueError("Cycle detected")
            return
        visited.add(node)
        stack.append(node)
        for neighbor in graph.get(node, []):
            dfs(neighbor)
        stack.pop()
        result.append(node)

    for node in graph:
        if node not in visited:
            dfs(node)
    return result[::-1]

if __name__ == "__main__":
    graph = {
        'A': ['B'],
        'B': ['C'],
        'C': ['A']
    }
    try:
        print(topological_sort_dfs(graph))
    except ValueError as e:
        print(e)

'''Topological sort using a priority queue (min-heap) for node selection.'''

import heapq

def topological_sort_pq(graph):
    '''Return topological order using a priority queue.'''
    in_degree = {node: 0 for node in graph}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    heap = [node for node in in_degree if in_degree[node] == 0]
    heapq.heapify(heap)
    result = []

    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(graph):
        raise ValueError("Graph has a cycle")
    return result

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': []
    }
    print(topological_sort_pq(graph))

'''Topological sort to determine the earliest possible order of tasks.'''

def task_order(graph):
    '''Return the earliest possible order of tasks using topological sort.'''
    in_degree = {task: 0 for task in graph}
    for task in graph:
        for dependent in graph[task]:
            in_degree[dependent] += 1

    queue = [task for task in in_degree if in_degree[task] == 0]
    result = []

    while queue:
        task = queue.pop(0)
        result.append(task)
        for dependent in graph[task]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

    if len(result) != len(graph):
        raise ValueError("Cycle detected in task dependencies")
    return result

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': []
    }
    print(task_order(graph))

