'''
Dynamic programming solution to the 0/1 knapsack problem.
'''

def knapsack(values, weights, capacity):
    """Solve the 0/1 knapsack problem using dynamic programming."""
    n = len(values)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacity = 50
    print(f"Maximum value: {knapsack(values, weights, capacity)}")

'''
Dynamic programming solution to the unbounded knapsack problem.
'''

def unbounded_knapsack(values, weights, capacity):
    """Solve the unbounded knapsack problem using dynamic programming."""
    dp = [0] * (capacity + 1)
    for w in range(capacity + 1):
        for i in range(len(values)):
            if weights[i] <= w:
                dp[w] = max(dp[w], dp[w - weights[i]] + values[i])
    return dp[capacity]

if __name__ == "__main__":
