    weights = [5, 10, 15]
    capacity = 20
    print(f"Maximum value: {unbounded_knapsack(values, weights, capacity)}")

'''
Dynamic programming solution to the 0/1 knapsack problem using memoization.
'''

def knapsack_memo(values, weights, capacity):
    """Solve the 0/1 knapsack problem using memoization."""
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def recurse(index, remaining):
        if index == 0 or remaining == 0:
            return 0
        if weights[index - 1] > remaining:
            return recurse(index - 1, remaining)
        return max(recurse(index - 1, remaining),
                   recurse(index - 1, remaining - weights[index - 1]) + values[index - 1])

    return recurse(len(values), capacity)

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacity = 50
    print(f"Maximum value: {knapsack_memo(values, weights, capacity)}")

