'''Detect cycles in a graph using DFS'''def has_cycle(graph, start):
    visited = set()
    recursion_stack = set()
    def dfs(node):
        if node in recursion_stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True
        recursion_stack.remove(node)
        return False
    return dfs(start)
