# Uses a stack to check if parentheses are balanced

def is_balanced(s):
    stack = []
    for char in s:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack:
                return False
            top = stack.pop()
            if (char == ")" and top != "(") or 
               (char == "}" and top != "{") or 
               (char == "]" and top != "["):
                return False
    return not stack

if __name__ == "__main__":
    test_strings = ["()", "({})", "({[}])", "(())"]
    for s in test_strings:
        print(f"{s}: {is_balanced(s)}")

