# A basic task scheduler using a queue

class Task:
    def __init__(self, name, priority=1):
        self.name = name
        self.priority = priority

    def __str__(self):
        return f"{self.name} (Priority: {self.priority})"

class TaskScheduler:
    def __init__(self):
        self.queue = []

    def add_task(self, task):
        self.queue.append(task)
        print(f"Added: {task}")

    def next_task(self):
        if not self.is_empty():
            task = self.queue.pop(0)
            print(f"Next task: {task}")
        else:
            print("No tasks to schedule.")

    def is_empty(self):
        return len(self.queue) == 0

if __name__ == "__main__":
    scheduler = TaskScheduler()
    scheduler.add_task(Task("Email", 2))
    scheduler.add_task(Task("Report", 1))
    scheduler.next_task()
    scheduler.next_task()

