'''Compares selection sort and merge sort for time and space.'''
import time

def selection_sort(arr):
    for i in range(len(arr)):
        min_idx = i
        for j in range(i + 1, len(arr)):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

if __name__ == '__main__':
    data = list(range(1000, 0, -1))

    start = time.time()
    selection_sort(data.copy())
    print(f'Selection Sort Time: {time.time() - start:.6f} seconds')

    start = time.time()
    merge_sort(data.copy())
    print(f'Merge Sort Time: {time.time() - start:.6f} seconds')

'''Implements a memoized Fibonacci function to save computation time.'''
import time

def fibonacci(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

if __name__ == '__main__':
    n = 30
    start = time.time()
    print(f'Fibonacci({n}) = {fibonacci(n)}')
    print(f'Time: {time.time() - start:.6f} seconds')

