'''
0/1 Knapsack solver using dynamic programming
'''
def knapsack_01(values, weights, capacity):
    n = len(values)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w - weights[i-1]] + values[i-1])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacity = 50
    print(f"Maximum value: {knapsack_01(values, weights, capacity)}")

'''
Unbounded Knapsack solver using dynamic programming
'''
def unbounded_knapsack(values, weights, capacity):
    dp = [0] * (capacity + 1)
    for w in range(capacity + 1):
        for i in range(len(values)):
            if weights[i] <= w:
                dp[w] = max(dp[w], dp[w - weights[i]] + values[i])
    return dp[capacity]

if __name__ == "__main__":
    values = [10, 30, 20]
    weights = [5, 10, 15]
    capacity = 50
    print(f"Maximum value: {unbounded_knapsack(values, weights, capacity)}")

'''
Knapsack solver with multiple constraints using dynamic programming
'''
def multi_constrained_knapsack(values, weights, capacities):
    n = len(values)
    dp = [[0] * (capacities[1] + 1) for _ in range(capacities[0] + 1)]
    for i in range(n):
        for w1 in range(capacities[0] + 1):
            for w2 in range(capacities[1] + 1):
                if weights[i][0] <= w1 and weights[i][1] <= w2:
                    dp[w1][w2] = max(dp[w1][w2], dp[w1 - weights[i][0]][w2 - weights[i][1]] + values[i])
    return dp[capacities[0]][capacities[1]]]

if __name__ == "__main__":
    values = [15, 20, 30]
    weights = [[10, 20], [15, 25], [20, 30]]
    capacities = [50, 70]
    print(f"Maximum value: {multi_constrained_knapsack(values, weights, capacities)}")

'''
Knapsack solver using memoization (top-down approach)
'''
def knapsack_memo(values, weights, capacity):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def helper(index, remaining):
        if index == len(values):
            return 0
        if weights[index] > remaining:
            return helper(index + 1, remaining)
        return max(
            helper(index + 1, remaining),
            helper(index + 1, remaining - weights[index]) + values[index]
        )

    return helper(0, capacity)

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacity = 50
    print(f"Maximum value: {knapsack_memo(values, weights, capacity)}")

