# kmp_search.py
"""Implement the Knuth-Morris-Pratt (KMP) algorithm for string matching."""

def compute_lps(pattern):
    """Compute the Longest Prefix Suffix (LPS) array for the pattern."""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def kmp_search(text, pattern):
    """Search for pattern in text using KMP algorithm."""
    lps = compute_lps(pattern)
    i = j = 0
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1
        if j == len(pattern):
            print(f"Pattern found at index {i - j}")
            j = lps[j - 1]
        elif i < len(text) and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

if __name__ == "__main__":
    text = input("Enter text: ")
    pattern = input("Enter pattern: ")
    kmp_search(text, pattern)

'''
Compare time and space tradeoffs between recursive and memoized Fibonacci calculations.
'''

def fibonacci_recursive(n):
    if n <= 1:
        return n
    return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)

def fibonacci_memo(n, memo={}):
    if n not in memo:
        memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
    return memo[n]

if __name__ == "__main__":
    import time
    for i in range(10, 30):
        start = time.time()
        fib = fibonacci_recursive(i)
        end = time.time()
        print(f"Recursive {i}: {end - start:.6f}s")

        start = time.time()
        fib = fibonacci_memo(i)
        end = time.time()
        print(f"Memoized {i}: {end - start:.6f}s")

