'''
Simulate LRU and FIFO cache eviction policies and compare time vs space usage.
'''

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key):
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return None

    def put(self, key, value):
        if key in self.cache:
            self.order.remove(key)
        elif len(self.cache) >= self.capacity:
            oldest = self.order.pop(0)
            del self.cache[oldest]
        self.cache[key] = value
        self.order.append(key)

class FIFOCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key):
        return self.cache.get(key)

    def put(self, key, value):
        if key in self.cache:
            return
        if len(self.cache) >= self.capacity:
            oldest = self.order.pop(0)
            del self.cache[oldest]
        self.cache[key] = value
        self.order.append(key)

if __name__ == "__main__":
    import time
    lru_cache = LRUCache(5)
    fifo_cache = FIFOCache(5)

    for i in range(10):
        lru_cache.put(i, i*2)
        fifo_cache.put(i, i*2)

    start = time.time()
    for i in range(10):
        lru_cache.get(i)
    end = time.time()
    print(f"LRU time: {end - start:.6f}s")

    start = time.time()
    for i in range(10):
        fifo_cache.get(i)
    end = time.time()
    print(f"FIFO time: {end - start:.6f}s")

'''
Compute the shortest path using Dijkstra's and A* algorithms and compare time vs space.
'''

import heapq

def dijkstra(graph, start, end):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_dist, current = heapq.heappop(priority_queue)
        if current == end:
            break
        if current_dist > distances[current]:
            continue
        for neighbor, weight in graph[current].items():
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
    return distances[end]

def a_star(graph, start, end, heuristic):
    open_set = [(0, start)]
    g_score = {node: float('inf') for node in graph}
    g_score[start] = 0
    came_from = {}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == end:
            break
        for neighbor, weight in graph[current].items():
            tentative_g = g_score[current] + weight
            if tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score = tentative_g + heuristic(neighbor)
                heapq.heappush(open_set, (f_score, neighbor))
    return g_score[end]

if __name__ == "__main__":
    graph = {
        'A': {'B': 1, 'C': 4},
        'B': {'A': 1, 'C': 2, 'D': 5},
        'C': {'A': 4, 'B': 2, 'D': 1},
        'D': {'B': 5, 'C': 1}
    }

    def heuristic(node):
        return 0  # Simple heuristic for A*

    print("Dijkstra's distance:", dijkstra(graph, 'A', 'D'))
    print("A* distance:", a_star(graph, 'A', 'D', heuristic))

'''
Compare time and space of binary search tree and hash table for storing and retrieving large datasets.
'''

import time

class BSTNode:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.left = None
        self.right = None

def insert_bst(root, key, value):
    if root is None:
        return BSTNode(key, value)
    if key < root.key:
        root.left = insert_bst(root.left, key, value)
    else:
        root.right = insert_bst(root.right, key, value)
    return root

def search_bst(root, key):
    if root is None:
        return None
    if root.key == key:
        return root.value
    elif key < root.key:
        return search_bst(root.left, key)
    else:
        return search_bst(root.right, key)

def build_bst(data):
    root = None
    for key, value in data.items():
        root = insert_bst(root, key, value)
    return root

def hash_table(data):
    return {key: value for key, value in data.items()}

if __name__ == "__main__":
    data = {i: f'value_{i}' for i in range(100000)}

    # BST
    start = time.time()
    bst_root = build_bst(data)
    end = time.time()
    print(f"BST insert time: {end - start:.6f}s")

    start = time.time()
    for i in range(100000):
        search_bst(bst_root, i)
    end = time.time()
    print(f"BST search time: {end - start:.6f}s")

    # Hash Table
    start = time.time()
    ht = hash_table(data)
    end = time.time()
    print(f"Hash table time: {end - start:.6f}s")

    start = time.time()
    for i in range(100000):
        ht[i]
    end = time.time()
    print(f"Hash table search time: {end - start:.6f}s")

