    target = 7
    result = binary_search(sorted_list, target)
    print(f'Element {target} found at index {result}' if result != -1 else f'Element {target} not found')

def binary_search_in_database(database, query):
    """Search for a query in a sorted database using binary search."""
    low, high = 0, len(database) - 1
    while low <= high:
        mid = (low + high) // 2
        if database[mid] == query:
            return mid
        elif database[mid] < query:
            low = mid + 1
        else:
            high = mid - 1
    return -1

