'''Dynamic programming solution for 0/1 knapsack problem.'''

def knapsack(weights, values, capacity):
    """Solve 0/1 knapsack problem using dynamic programming."""
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w - weights[i-1]] + values[i-1])
            else:
                dp[i][w] = dp[i-1][w]

    return dp[n][capacity]

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(f"Maximum value: {knapsack(weights, values, capacity)}")

'''Dynamic programming solution for unbounded knapsack problem.'''

def unbounded_knapsack(values, weights, capacity):
    """Solve unbounded knapsack problem using dynamic programming."""
    dp = [0] * (capacity + 1)

    for w in range(capacity + 1):
        for i in range(len(weights)):
            if weights[i] <= w:
                dp[w] = max(dp[w], dp[w - weights[i]] + values[i])

    return dp[capacity]

if __name__ == "__main__":
    values = [10, 30, 50]
    weights = [1, 2, 3]
    capacity = 5
    print(f"Maximum value: {unbounded_knapsack(values, weights, capacity)}")

'''Dynamic programming solution for knapsack using memoization.'''

def knapsack_memo(weights, values, capacity):
    """Solve knapsack problem using memoization."""
    memo = {}

    def helper(i, w):
        if i == 0 or w == 0:
            return 0
        if (i, w) in memo:
            return memo[(i, w)]
        if weights[i-1] > w:
            result = helper(i-1, w)
        else:
            result = max(helper(i-1, w), helper(i-1, w - weights[i-1]) + values[i-1])
        memo[(i, w)] = result
        return result

    return helper(len(weights), capacity)

if __name__ == "__main__":
    weights = [1, 2, 3]
    values = [10, 15, 40]
    capacity = 4
    print(f"Maximum value: {knapsack_memo(weights, values, capacity)}")

'''Dynamic programming solution for 2D knapsack problem.'''

def two_d_knapsack(values, weights, volumes, capacity_w, capacity_v):
    """Solve knapsack problem with two constraints: weight and volume."""
    n = len(values)
    dp = [[[0] * (capacity_v + 1) for _ in range(capacity_w + 1)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity_w + 1):
            for v in range(capacity_v + 1):
                if weights[i-1] <= w and volumes[i-1] <= v:
                    dp[i][w][v] = max(dp[i-1][w][v], dp[i-1][w - weights[i-1]][v - volumes[i-1]] + values[i-1])
                else:
                    dp[i][w][v] = dp[i-1][w][v]

    return dp[n][capacity_w][capacity_v]

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    volumes = [5, 10, 15]
    capacity_w = 50
    capacity_v = 30
    print(f"Maximum value: {two_d_knapsack(values, weights, volumes, capacity_w, capacity_v)}")

