'''Handle division by zero with a custom exception'''
class DivisionByZeroError(Exception):
    """Raised when division by zero is attempted"""

    def __init__(self, message="Cannot divide by zero"):
        self.message = message
        super().__init__(self.message)

def divide(a, b):
    if b == 0:
        raise DivisionByZeroError()
    return a / b

if __name__ == "__main__":
    try:
        result = divide(10, 0)
    except DivisionByZeroError as e:
        print(f"Error: {e}")

'''
This script demonstrates the use of property decorators to manage a temperature attribute in a class.
'''
class Temperature:
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("Temperature below -273.15 is not possible")
        self._celsius = value

    @property
    def fahrenheit(self):
        return (self._celsius * 9/5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        self._celsius = (value - 32) * 5/9

# Example usage
temp = Temperature(25)
print(f"Celsius: {temp.celsius}")
print(f"Fahrenheit: {temp.fahrenheit}")
temp.fahrenheit = 98.6
print(f"Celsius after update: {temp.celsius}")

'''
This script uses a descriptor to manage access to a class attribute.
