'''Decorator to measure function execution time'''
import time
def timer_decorator(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f'{func.__name__} executed in {end - start:.4f} seconds')
        return result
    return wrapper

@timer_decorator
def slow_function():
    time.sleep(2)

slow_function()

'''Decorator to cache function results'''
def cache_decorator(func):
    cache = {}
    def wrapper(*args):
        if args in cache:
            print(f'Using cached result for {func.__name__}({args})')
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    return wrapper

@cache_decorator
def add(a, b):
    return a + b

print(add(2, 3))
print(add(2, 3))

'''Decorator to enforce type checking on function arguments'''
def type_check_decorator(func):
    def wrapper(*args, **kwargs):
        for i, arg in enumerate(args):
            if not isinstance(arg, func.__annotations__.get('args', {}).get(i)):
                raise TypeError(f'Argument {i} must be of type {func.__annotations__.get("args", {}).get(i)}')
        return func(*args, **kwargs)
    return wrapper

@type_check_decorator
def multiply(a: int, b: int):
    return a * b

print(multiply(2, 3))
try:
    print(multiply('2', 3))
except TypeError as e:
    print(e)

