# fib_memo.py
# Computes Fibonacci numbers using memoization

def fibonacci_memo(n, memo={}):
    """Returns the nth Fibonacci number using memoization."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if n == 1:
        return 1
    memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
    return memo[n]

if __name__ == "__main__":
    import sys
    n = int(sys.argv[1])
    print(fibonacci_memo(n))

# fib_dp_memo.py
# Calculates Fibonacci numbers using both dynamic programming and memoization

def fibonacci_dp_memo(n):
    """Returns the nth Fibonacci number using dynamic programming and memoization."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    memo = {}
    def helper(x):
        if x in memo:
            return memo[x]
        if x == 0:
            return 0
        if x == 1:
            return 1
        memo[x] = helper(x - 1) + helper(x - 2)
        return memo[x]
    return helper(n)

if __name__ == "__main__":
    import sys
    n = int(sys.argv[1])
    print(fibonacci_dp_memo(n))

