# A hash table with a custom hashing function and resizing capability
class ResizableHash:
    def __init__(self, capacity=8):
        self.capacity = capacity
        self.table = [[] for _ in range(capacity)]
        self.size = 0

    def _hash(self, key):
        # Custom hash function: sum of character codes
        return sum(ord(c) for c in str(key)) % self.capacity

    def _resize(self):
        new_capacity = self.capacity * 2
        new_table = [[] for _ in range(new_capacity)]
        for bucket in self.table:
            for key, value in bucket:
                index = sum(ord(c) for c in str(key)) % new_capacity
                new_table[index].append((key, value))
        self.capacity = new_capacity
        self.table = new_table

    def insert(self, key, value):
        if self.size / self.capacity > 0.7:
            self._resize()
        index = self._hash(key)
        for i, (k, v) in enumerate(self.table[index]):
            if k == key:
                self.table[index][i] = (key, value)
                return
        self.table[index].append((key, value))
        self.size += 1

    def get(self, key):
        index = self._hash(key)
        for k, v in self.table[index]:
            if k == key:
                return v
        return None

