def dfs_path(graph, start, end):
    """Perform DFS and return the path from start to end.\n\n    Args:
        graph (dict): Adjacency list of the graph.
        start (str): Starting node.
        end (str): Target node to find.
    Returns:
        list: Path from start to end, or None if not found.
    """
    stack = [(start, [start])]
    visited = set()
    while stack:
        node, path = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == end:
                return path
            for neighbor in reversed(graph[node]):
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
    return None

