'''Topological sort implementation for a directed acyclic graph'''def topological_sort(graph):
    '''Perform topological sort on a graph represented as an adjacency list.
    Returns a list of nodes in topological order.
    '''
    in_degree = {node: 0 for node in graph}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1
    queue = [node for node in in_degree if in_degree[node] == 0]
    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return result

