'''Topological sort using DFS with cycle detection'''def topological_sort_dfs(graph):
    '''Perform topological sort using DFS with cycle detection.
    Returns a list of nodes in topological order or raises an error if a cycle is detected.
    '''
    visited = set()
    result = []
    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)
        result.append(node)
    for node in graph:
        if node not in visited:
            dfs(node)
    return result[::-1]

