def mergesort(arr, compare):
    """Sorts an array using mergesort with a custom comparison function."""
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = mergesort(arr[:mid], compare)
    right = mergesort(arr[mid:], compare)
    return merge(left, right, compare)

def merge(left, right, compare):
    """Merges two sorted lists using the custom comparison function."""
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if compare(left[i], right[j]):
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

