# Compares thread performance with and without the GIL in Python

import threading
import time
import concurrent.futures

def cpu_intensive_task():
    count = 0
    for _ in range(1000000):
        count += 1
    return count

def run_threads_with_gil():
    threads = [threading.Thread(target=cpu_intensive_task) for _ in range(4)]
    start_time = time.time()
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return time.time() - start_time

def run_threads_without_gil():
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
        start_time = time.time()
        futures = [executor.submit(cpu_intensive_task) for _ in range(4)]
        for future in concurrent.futures.as_completed(futures):
            future.result()
    return time.time() - start_time

def main():
    print("Time with GIL (threading):", run_threads_with_gil())
    print("Time without GIL (ThreadPoolExecutor):", run_threads_without_gil())

if __name__ == "__main__":
    main()

