'''Dynamic programming with memoization for the 0/1 knapsack problem.'''

def knapsack_memo(weights, values, capacity):
    memo = {}

    def helper(i, remaining):
        if (i, remaining) in memo:
            return memo[(i, remaining)]
        if i == 0 or remaining == 0:
            return 0
        if weights[i - 1] > remaining:
            memo[(i, remaining)] = helper(i - 1, remaining)
            return memo[(i, remaining)]
        else:
            include = values[i - 1] + helper(i - 1, remaining - weights[i - 1])
            exclude = helper(i - 1, remaining)
            memo[(i, remaining)] = max(include, exclude)
            return memo[(i, remaining)]
    return helper(len(weights), capacity)

if __name__ == "__main__":
    weights = [2, 3, 4]
    values = [3, 4, 5]
    capacity = 5
    print(f"Maximum value: {knapsack_memo(weights, values, capacity)}")

'''Solves the fractional knapsack problem using a greedy approach with sorting.'''

def fractional_knapsack(values, weights, capacity):
    items = sorted(zip(weights, values), key=lambda x: x[1]/x[0], reverse=True)
    total_value = 0.0
    for weight, value in items:
        if capacity == 0:
            break
        if weight <= capacity:
            total_value += value
            capacity -= weight
        else:
            total_value += (value / weight) * capacity
            capacity = 0
    return total_value

