    values = [60, 100, 120]
    capacity = 50
    print(f"Maximum value: {fractional_knapsack(weights, values, capacity)}")

'''Dynamic programming for multi-constraint knapsack problem.'''

def multi_knapsack(values, weights, capacities):
    n = len(values)
    m = len(capacities)

    # Create a 3D DP table: dp[i][w1][w2] ... 
    # This is simplified to 2D for 2 constraints
    if m != 2:
        raise ValueError("Only 2 constraints are supported")

    dp = [[0] * (capacities[1] + 1) for _ in range(capacities[0] + 1)]

    for i in range(n):
        for w1 in range(capacities[0], -1, -1):
            for w2 in range(capacities[1], -1, -1):
                if weights[i][0] <= w1 and weights[i][1] <= w2:
                    dp[w1][w2] = max(dp[w1][w2], dp[w1 - weights[i][0]][w2 - weights[i][1]] + values[i])
    return dp[capacities[0]][capacities[1]]

