def two_pointer_sum(arr, target):
    """Finds pairs in a sorted array that sum to the target using two pointers."""
    left = 0
    right = len(arr) - 1
    results = []
    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            results.append((arr[left], arr[right]))
            left += 1
            right -= 1
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return results

