class Temperature:
    """A class to represent temperature with property validation."""
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("Temperature cannot be below absolute zero.")
        self._celsius = value

    @property
    def fahrenheit(self):
        return (self._celsius * 9/5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        self._celsius = (value - 32) * 5/9

if __name__ == "__main__":
    t = Temperature(25)
    print(f"Celsius: {t.celsius}, Fahrenheit: {t.fahrenheit}")
    t.celsius = 30
    print(f"Celsius: {t.celsius}, Fahrenheit: {t.fahrenheit}")

class BalanceDescriptor:
    """A descriptor that manages a bank account balance."""
    def __init__(self):
        self._balance = 0

    def __get__(self, instance, owner):
        return self._balance

    def __set__(self, instance, value):
        if value < 0:
            raise ValueError("Balance cannot be negative.")
        self._balance = value

    def __delete__(self, instance):
        del self._balance

class BankAccount:
    balance = BalanceDescriptor()

    def __init__(self, initial_balance=0):
        self.balance = initial_balance

if __name__ == "__main__":
    account = BankAccount(100)
    print(f"Account balance: {account.balance}")
    try:
        account.balance = -50
    except ValueError as e:
        print(f"Error: {e}")

class AccessCounter:
    """A descriptor that tracks the number of times an attribute is accessed."""
    def __init__(self, initial_value=None):
        self._value = initial_value
        self._access_count = 0

    def __get__(self, instance, owner):
        self._access_count += 1
        return self._value

    def __set__(self, instance, value):
        self._value = value

    def __delete__(self, instance):
        del self._value

class Data:
    counter = AccessCounter(10)

    def __init__(self, value):
        self.counter = value

if __name__ == "__main__":
    data = Data(20)
    print(f"Counter value: {data.counter}")
    print(f"Access count: {data.counter._access_count}")

class TypeCheck:
    """A descriptor that enforces type checking on an attribute."""
    def __init__(self, type):
        self._type = type

    def __get__(self, instance, owner):
        return instance.__dict__.get(self._type, None)

    def __set__(self, instance, value):
        if not isinstance(value, self._type):
            raise TypeError(f"Value must be of type {self._type.__name__}")
        instance.__dict__[self._type] = value

class Person:
    name = TypeCheck(str)
    age = TypeCheck(int)

    def __init__(self, name, age):
        self.name = name
        self.age = age

if __name__ == "__main__":
    person = Person("Alice", 30)
    print(f"Name: {person.name}, Age: {person.age}")
    try:
        person.age = "thirty"
    except TypeError as e:
        print(f"Error: {e}")

class Lazy:
    """A descriptor that lazily initializes an object on first access."""
    def __init__(self, cls):
        self._cls = cls
        self._instance = None

    def __get__(self, instance, owner):
        if self._instance is None:
            self._instance = self._cls()
        return self._instance

class Database:
    def connect(self):
        print("Connecting to database...")

class App:
    db = Lazy(Database)

    def __init__(self):
        pass

if __name__ == "__main__":
    app = App()
    print("Accessing db...")
    app.db.connect()

class Config:
