    @debug_mode.setter
    def debug_mode(self, value):
        if not isinstance(value, bool):
            raise ValueError("debug_mode must be a boolean.")
        self._debug_mode = value

    @property
    def log_level(self):
        return self._log_level

    @log_level.setter
