# bubble_sort_explanation.py
# Implements bubble sort and discusses its inefficiency

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

if __name__ == "__main__":
    sample = [64, 34, 25, 12, 22, 11, 90]
    sorted_arr = bubble_sort(sample)
    print("Sorted array:", sorted_arr)
    print("\nBubble sort is inefficient for large datasets as it has O(n^2) time complexity.")

