# dijkstra_from_file.py
# Reads a graph from a file and finds the shortest path using Dijkstra's algorithm

import heapq
import sys

def parse_graph_file(filename):
    """Parses a graph file into a dictionary."""
    graph = {}
    with open(filename, 'r') as f:
        for line in f:
            parts = line.strip().split()
            if not parts:
                continue
            if parts[0] == 'node':
                node = parts[1]
                graph[node] = {}
            elif parts[0] == 'edge':
                src, dest, weight = parts[1], parts[2], parts[3]
                graph[src][dest] = weight
    return graph

def dijkstra(graph, start):
    """Finds the shortest path from start to all other nodes in a weighted graph."""
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        current_dist, current_node = heapq.heappop(heap)
        if current_dist > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            weight = int(weight)
            new_dist = current_dist + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))
    return distances

# Example usage
if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python dijkstra_from_file.py <filename>")
        sys.exit(1)
    graph = parse_graph_file(sys.argv[1])
    print(dijkstra(graph, 'A'))

