# separate_chaining.py
# Implements a hash table with separate chaining and calculates load factor
class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [[] for _ in range(size)]
        self.count = 0

    def _hash(self, key):
        return hash(key) % self.size

    def insert(self, key, value):
        index = self._hash(key)
        for k, v in self.table[index]:
            if k == key:
                return
        self.table[index].append((key, value))
        self.count += 1

    def get(self, key):
        index = self._hash(key)
        for k, v in self.table[index]:
            if k == key:
                return v
        return None

    def load_factor(self):
        return self.count / self.size

    def __str__(self):
        return '\n'.join([f'{i}: {self.table[i]}' for i in range(self.size)])

if __name__ == '__main__':
    ht = HashTable()
    ht.insert('a', 1)
    ht.insert('b', 2)
    ht.insert('c', 3)
    print(f'Load factor: {ht.load_factor()}')

# open_addressing.py
# Implements a hash table with open addressing and linear probing
class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [None] * size

    def _hash(self, key):
        return hash(key) % self.size

    def insert(self, key, value):
        index = self._hash(key)
        while self.table[index] is not None:
            index = (index + 1) % self.size
        self.table[index] = (key, value)

    def get(self, key):
        index = self._hash(key)
        while self.table[index] is not None:
            if self.table[index][0] == key:
                return self.table[index][1]
            index = (index + 1) % self.size
        return None

    def __str__(self):
        return '\n'.join([f'{i}: {self.table[i]}' for i in range(self.size)])

if __name__ == '__main__':
    ht = HashTable()
    ht.insert('a', 1)
    ht.insert('b', 2)
    print(ht.get('a'))

