# Uses DFS to detect cycles in a graph

graph = {
    'A': ['B', 'C'],
    'B': ['D', 'A'],
    'C': ['D'],
    'D': ['C']
}

def has_cycle(graph):
    visited = set()
    recursion_stack = set()
    def _dfs(node):
        if node in recursion_stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph[node]:
            if _dfs(neighbor):
                return True
        recursion_stack.remove(node)
        return False
    for node in graph:
        if _dfs(node):
            return True
    return False

if __name__ == '__main__':
