        ([5, 2, 9, 1, 5, 6], [1, 2, 5, 5, 6, 9]),
        ([], []),
        ([1], [1])
    ]
    for i, (input_list, expected) in enumerate(test_cases):
        result = merge_sort(input_list)
        assert result == expected, f"Test {i+1} failed: {input_list} => {result} != {expected}"
    print("All tests passed!")

