Time vs Space Tradeoffs: Fibonacci with Memoization
'''
def fibonacci(n, memo=None):
    '''Calculate nth Fibonacci number with memoization.'''
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

