'''
Time vs Space Tradeoffs: Data Search Algorithms
'''
import random
import time

def generate_data(size):
    return [random.randint(1, 1000) for _ in range(size)]

def linear_search(data, target):
    for i, num in enumerate(data):
        if num == target:
            return i
    return -1

def binary_search(data, target):
    low, high = 0, len(data) - 1
    while low <= high:
        mid = (low + high) // 2
        if data[mid] == target:
            return mid
        elif data[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def main():
    data = generate_data(100000)
    data.sort()
    target = 500

    start = time.time()
    print('Linear search result:', linear_search(data, target))
    print('Linear search time:', time.time() - start, 'seconds')

    start = time.time()
    print('Binary search result:', binary_search(data, target))
    print('Binary search time:', time.time() - start, 'seconds')

if __name__ == '__main__':
    main()

