    s = "abcabcbb"
    print(f"Longest substring without repeating characters: {longest_unique_substring(s)}")

'''Counts the number of anagrams of a given string in another string using the sliding window technique.'''

def count_anagrams(s, p):
    if len(p) > len(s):
        return 0
    p_count = [0] * 26
    s_count = [0] * 26
    for i in range(len(p)):
        p_count[ord(p[i]) - ord('a')] += 1
        s_count[ord(s[i]) - ord('a')] += 1
    count = 0
    for i in range(len(p), len(s)):
        if p_count == s_count:
            count += 1
        s_count[ord(s[i - len(p)]) - ord('a')] -= 1
        s_count[ord(s[i]) - ord('a')] += 1
    if p_count == s_count:
        count += 1
    return count

if __name__ == "__main__":
    s = "cbaabcc"
    p = "abc"
    print(f"Number of anagrams: {count_anagrams(s, p)}")

'''Counts the number of subarrays with sum exactly equal to k using sliding window technique.'''

def count_subarrays_sum_k(arr, k):
    if not arr:
        return 0
    count = 0
    current_sum = 0
    left = 0
    for right in range(len(arr)):
        current_sum += arr[right]
        while current_sum > k and left <= right:
            current_sum -= arr[left]
            left += 1
        if current_sum == k:
            count += 1
    return count

if __name__ == "__main__":
    arr = [1, 1, 1, 1, 1]
    k = 2
    print(f"Number of subarrays with sum {k}: {count_subarrays_sum_k(arr, k)}")

'''Finds the maximum number of vowels in any substring of a given length using the sliding window technique.'''

def max_vowels(s, k):
    vowels = set('aeiou')
    max_count = 0
    current_count = 0
    for i in range(k):
        if s[i] in vowels:
            current_count += 1
    max_count = current_count
    for i in range(k, len(s)):
        if s[i - k] in vowels:
            current_count -= 1
        if s[i] in vowels:
            current_count += 1
        if current_count > max_count:
            max_count = current_count
    return max_count

