def select_pivot(arr, low, high, method="mid"):
    """Selects a pivot based on the given method."""
    if method == "first":
        return low
    elif method == "last":
        return high
    elif method == "mid":
        return (low + high) // 2
    else:
        return random.randint(low, high)

def quicksort(arr, low, high, pivot_method="mid"):
    """Sorts an array using quicksort with a customizable pivot selection."""
    if low < high:
        pi = partition(arr, low, high, select_pivot(arr, low, high, pivot_method))
        quicksort(arr, low, pi - 1, pivot_method)
        quicksort(arr, pi + 1, high, pivot_method)

def partition(arr, low, high, pivot_idx):
    pivot_val = arr[pivot_idx]
    arr[pivot_idx], arr[high] = arr[high], arr[pivot_idx]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot_val:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

