'''Compares dictionary and list for counting word frequencies''' 

from collections import defaultdict

def count_with_dict(words):
    counts = defaultdict(int)
    for word in words:
        counts[word] += 1
    return counts

def count_with_list(words):
    counts = []
    for word in words:
        found = False
        for i, (w, c) in enumerate(counts):
            if w == word:
                counts[i] = (w, c+1)
                found = True
                break
        if not found:
            counts.append((word, 1))
    return counts

if __name__ == "__main__":
    text = "apple banana apple cherry banana apple"
    words = text.split()
    print("Dictionary count:", count_with_dict(words))
    print("List count:", count_with_list(words))

'''Compares binary search tree and array for median calculation''' 

import sys
import random

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_node(root, value):
    if root is None:
        return Node(value)
    if value < root.value:
        root.left = insert_node(root.left, value)
    else:
        root.right = insert_node(root.right, value)
    return root

def inorder_traversal(root, result):
    if root:
        inorder_traversal(root.left, result)
        result.append(root.value)
        inorder_traversal(root.right, result)

if __name__ == "__main__":
    data = [random.randint(1, 100) for _ in range(100)]
    sorted_data = sorted(data)
    print(f"Array median: {sorted_data[len(sorted_data)//2]}")

    root = None
    for num in data:
        root = insert_node(root, num)
    in_order = []
    inorder_traversal(root, in_order)
    print(f"BST median: {in_order[len(in_order)//2]}")

