'''0/1 Knapsack Dynamic Programming Solution'''def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

if __name__ == '__main__':
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(f'Max value: {knapsack(weights, values, capacity)}')

'''Unbounded Knapsack with Memoization'''from functools import lru_cache
def unbounded_knapsack(weights, values, capacity):
    @lru_cache(maxsize=None)
    def dp(w):
        if w == 0:
            return 0
        max_val = 0
        for i in range(len(weights)):
            if weights[i] <= w:
                max_val = max(max_val, values[i] + dp(w - weights[i]))
        return max_val
    return dp(capacity)

if __name__ == '__main__':
    weights = [1, 3, 4]
    values = [15, 20, 50]
    capacity = 5
    print(f'Max value: {unbounded_knapsack(weights, values, capacity)}')

'''Knapsack with Recursive Memoization'''from functools import lru_cache
def knapsack(weights, values, capacity):
    @lru_cache(maxsize=None)
    def dp(index, remaining):
        if index == 0 or remaining == 0:
            return 0
        if weights[index - 1] > remaining:
            return dp(index - 1, remaining)
        else:
            return max(
                dp(index - 1, remaining),
                values[index - 1] + dp(index - 1, remaining - weights[index - 1])
            )
    return dp(len(weights), capacity)

if __name__ == '__main__':
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(f'Max value: {knapsack(weights, values, capacity)}')

