'''Two Pointers Technique to find if a target sum exists in a sorted list'''def two_pointer_sum(sorted_list, target):
    left = 0
    right = len(sorted_list) - 1
    while left < right:
        current_sum = sorted_list[left] + sorted_list[right]
        if current_sum == target:
            return True
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return False

