def dfs_paths(graph, start, end):
    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        for neighbor in graph[node]:
            if neighbor == end:
                yield path + [neighbor]
            else:
                stack.append((neighbor, path + [neighbor]))

