'''Find the k largest elements in a list using a heap'''

def find_k_largest(nums, k):
    if k <= 0 or k > len(nums):
        return []
    # Use a min-heap to keep the k largest elements
    heap = nums[:k]
    heapq.heapify(heap)
    for num in nums[k:]:
