import heapq

def median_stream(numbers):
    '''Find the median of a stream of numbers using two heaps'''
    max_heap = []  # to store the lower half (max-heap simulated by negating values)
    min_heap = []  # to store the upper half (min-heap)

    for num in numbers:
        if not max_heap or num < -max_heap[0]:
            heapq.heappush(max_heap, -num)
        else:
            heapq.heappush(min_heap, num)

        # Balance heaps
        if len(max_heap) > len(min_heap) + 1:
            heapq.heappush(min_heap, -heapq.heappop(max_heap))
        elif len(min_heap) > len(max_heap):
            heapq.heappush(max_heap, -heapq.heappop(min_heap))

        # Get median
        if len(max_heap) == len(min_heap):
            yield (-max_heap[0] + min_heap[0]) / 2
        else:
            yield -max_heap[0]

# Example usage
if __name__ == "__main__":
    stream = [3, 1, 4, 2, 5]
    for i, m in enumerate(median_stream(stream)):
        print(f"Median after {i+1} numbers: {m}")

