'''Dynamic programming solution for 0/1 knapsack problem.'''

def knapsack(values, weights, capacity):
    n = len(values)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacity = 50
    print(f"Maximum value: {knapsack(values, weights, capacity)}")

'''Dynamic programming solution for unbounded knapsack problem.'''

def unbounded_knapsack(values, weights, capacity):
    n = len(values)
    dp = [0] * (capacity + 1)

    for w in range(capacity + 1):
        for i in range(n):
            if weights[i] <= w:
                dp[w] = max(dp[w], dp[w - weights[i]] + values[i])
    return dp[capacity]

if __name__ == "__main__":
    values = [10, 30, 20]
    weights = [5, 10, 15]
    capacity = 20
    print(f"Maximum value: {unbounded_knapsack(values, weights, capacity)}")

'''Dynamic programming solution for knapsack using memoization.'''

def knapsack_memo(values, weights, capacity):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def helper(index, remaining):
        if index == 0 or remaining == 0:
            return 0
        if weights[index - 1] > remaining:
            return helper(index - 1, remaining)
        return max(helper(index - 1, remaining), 
                        helper(index - 1, remaining - weights[index - 1]) + values[index - 1])

    return helper(len(values), capacity)

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacity = 50
    print(f"Maximum value: {knapsack_memo(values, weights, capacity)}")

