"""
Validates that a given path points to a CSV file.
"""
import argparse
import os

def is_csv_file(path):
    return os.path.isfile(path) and path.lower().endswith('.csv')

def main():
    parser = argparse.ArgumentParser(description='Validate a CSV file path')
    parser.add_argument('file_path', type=str, help='Path to the CSV file')
    args = parser.parse_args()
    if is_csv_file(args.file_path):
        print(f'Valid CSV file: {args.file_path}')
    else:
        print(f'Invalid CSV file: {args.file_path}')

if __name__ == '__main__':
    main()

