'''
Depth-First Search on a graph represented as an adjacency list.
'''

def dfs(graph, start):
    visited = set()
    def _dfs(node):
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                _dfs(neighbor)
    _dfs(start)
    return visited

if __name__ == "__main__":
    # Example graph
    graph = {
        'A': ['B', 'C'],
        'B': ['A', 'D'],
        'C': ['A', 'D'],
        'D': ['B', 'C']
    }
    result = dfs(graph, 'A')
    print("Visited nodes:", result)

'''
Finds all paths from a start node to an end node using DFS.
'''

def dfs_paths(graph, start, end):
    paths = []
    def _dfs(node, path):
        if node == end:
            paths.append(path.copy())
            return
        for neighbor in graph[node]:
            if neighbor not in path:
                path.append(neighbor)
                _dfs(neighbor, path)
                path.pop()
    _dfs(start, [start])
    return paths

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['A', 'D'],
        'C': ['A', 'D'],
        'D': ['B', 'C']
    }
    result = dfs_paths(graph, 'A', 'D')
    print("All paths from A to D:", result)

'''
Performs DFS on a directed graph and returns the traversal order.
'''

def dfs_directed(graph, start):
    visited = set()
    traversal = []
    def _dfs(node):
        if node not in visited:
            visited.add(node)
            traversal.append(node)
            for neighbor in graph[node]:
                _dfs(neighbor)
    _dfs(start)
    return traversal

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': []
    }
    result = dfs_directed(graph, 'A')
    print("Traversal order:", result)

'''
Detects cycles in a graph using DFS.
'''

def has_cycle(graph):
    visited = set()
    recursion_stack = set()

    def _dfs(node):
        if node in recursion_stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph[node]:
            if _dfs(neighbor):
                return True
        recursion_stack.remove(node)
        return False

    for node in graph:
        if _dfs(node):
            return True
    return False

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': ['B']
    }
    result = has_cycle(graph)
    print("Cycle detected:", result)

'''
Counts the number of connected components in a graph using DFS.
'''

def count_components(graph):
    visited = set()
    components = 0

    def _dfs(node):
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                _dfs(neighbor)

    for node in graph:
        if node not in visited:
            _dfs(node)
            components += 1

    return components

if __name__ == "__main__":
    graph = {
        'A': ['B'],
        'B': ['A'],
        'C': ['D'],
        'D': ['C'],
        'E': []
    }
    result = count_components(graph)
    print("Number of connected components:", result)

class HashTable:
    """A simple hash table implementation using open addressing."

    Attributes:
        size: The size of the hash table.
        table: A list to store key-value pairs.
    """

    def __init__(self, size=10):
        self.size = size
        self.table = [None] * self.size

    def _hash(self, key):
        """Compute the hash index for a given key."
        return hash(key) % self.size

    def insert(self, key, value):
        """Insert a key-value pair into the hash table."
        index = self._hash(key)
        while self.table[index] is not None:
            index = (index + 1) % self.size
        self.table[index] = (key, value)

    def get(self, key):
        """Retrieve the value associated with a given key."
        index = self._hash(key)
        while self.table[index] is not None:
            if self.table[index][0] == key:
                return self.table[index][1]
            index = (index + 1) % self.size
        raise KeyError(f'Key not found: {key}')

    def __str__(self):
        return str({k: v for k, v in self.table if v is not None})

if __name__ == "__main__":
    ht = HashTable()
    ht.insert("name", "Alice")
    ht.insert("age", 30)
    print(ht.get("name"))  # Output: Alice
    print(ht.get("age"))   # Output: 30
    print(ht)

