from collections import OrderedDict

class LRUCache:
    """A cache with LRU (Least Recently Used) eviction policy."

    Attributes:
        capacity: The maximum number of items the cache can hold.
    """

    def __init__(self, capacity=10):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        """Retrieve the value for a key, or return None if not found."
        if key in self.cache:
            self.cache.move_to_end(key)
            return self.cache[key]
        return None

    def put(self, key, value):
        """Insert a key-value pair into the cache."
        if key in self.cache:
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
        self.cache[key] = value

    def __str__(self):
        return str(self.cache)

if __name__ == "__main__":
    cache = LRUCache(3)
    cache.put("a", 1)
    cache.put("b", 2)
    cache.put("c", 3)
    print(cache.get("a"))  # Output: 1
    cache.put("d", 4)
    print(cache)  # Output: OrderedDict([('b', 2), ('c', 3), ('d', 4)])

# sliding_window.py
# Finds the longest substring without repeating characters using the sliding window technique

def longest_unique_substring(s):
    char_index = {}
    max_length = 0
    left = 0
    for right, char in enumerate(s):
        if char in char_index and char_index[char] >= left:
            left = char_index[char] + 1
        char_index[char] = right
        max_length = max(max_length, right - left + 1)
    return max_length

# Example usage
if __name__ == "__main__":
    text = "abcabcbb"
    print(f"Longest unique substring length: {longest_unique_substring(text)}")

# sliding_window.py
# Finds the maximum number of vowels in a substring of length k using the sliding window technique

def max_vowels(s, k):
    vowels = set('aeiouAEIOU')
    count = 0
    max_count = 0
    for i in range(len(s)):
        if i >= k:
            if s[i - k] in vowels:
                count -= 1
        if s[i] in vowels:
            count += 1
        max_count = max(max_count, count)
    return max_count

# Example usage
if __name__ == "__main__":
    text = "abcii"
    k = 2
    print(f"Maximum vowels in a substring of length {k}: {max_vowels(text, k)}")

