'''0/1 Knapsack using Dynamic Programming'''def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

if __name__ == '__main__':
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(f"Maximum value: {knapsack(weights, values, capacity)}")

'''Unbounded Knapsack using Dynamic Programming'''def unbounded_knapsack(weights, values, capacity):
    n = len(weights)
    dp = [0] * (capacity + 1)
    for w in range(1, capacity + 1):
        for i in range(n):
            if weights[i] <= w:
                dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

if __name__ == '__main__':
    weights = [1, 3, 4]
    values = [15, 20, 30]
    capacity = 8
    print(f"Maximum value: {unbounded_knapsack(weights, values, capacity)}")

'''Knapsack using Memoization'''def knapsack_memo(weights, values, capacity):
    memo = {}
    def helper(index, remaining):
        if index == 0 or remaining == 0:
            return 0
        if (index, remaining) in memo:
            return memo[(index, remaining)]
        if weights[index - 1] > remaining:
            memo[(index, remaining)] = helper(index - 1, remaining)
            return memo[(index, remaining)]
        else:
            include = values[index - 1] + helper(index - 1, remaining - weights[index - 1])
            exclude = helper(index - 1, remaining)
            memo[(index, remaining)] = max(include, exclude)
            return memo[(index, remaining)]
    return helper(len(weights), capacity)

if __name__ == '__main__':
    weights = [2, 3, 4]
    values = [3, 4, 5]
    capacity = 5
    print(f"Maximum value: {knapsack_memo(weights, values, capacity)}")

'''Multi-Constraint Knapsack Problem'''def multi_knapsack(weights, values, capacities):
    n = len(weights)
    m = len(capacities)
    dp = [[[0] * (capacities[j] + 1) for j in range(m)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(m):
            for w in range(1, capacities[j] + 1):
                if weights[i - 1] <= w:
                    dp[i][j][w] = max(dp[i - 1][j][w], values[i - 1] + dp[i - 1][j][w - weights[i - 1]])
                else:
                    dp[i][j][w] = dp[i - 1][j][w]
    return dp[n][m - 1][capacities[m - 1]]

if __name__ == '__main__':
    weights = [2, 3, 4]
    values = [3, 4, 5]
    capacities = [5, 7]
    print(f"Maximum value: {multi_knapsack(weights, values, capacities)}")

'''Memoized Fibonacci sequence calculator'''def fib(n, memo=None):
    """Calculate the nth Fibonacci number using memoization."""
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fib(n-1, memo) + fib(n-2, memo)
    return memo[n]

