'''Memoized factorial calculator'''def factorial(n, memo=None):
    """Calculate the factorial of a number using memoization."""
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 1
    memo[n] = n * factorial(n-1, memo)
    return memo[n]

