'''Memoized prime number checker'''def is_prime(n, memo=None):
    """Check if a number is prime, using memoization to cache results."""
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        memo[n] = False
        return False
    if n <= 3:
        memo[n] = True
        return True
    if n % 2 == 0 or n % 3 == 0:
        memo[n] = False
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            memo[n] = False
            return False
        i += 6
    memo[n] = True
    return True

if __name__ == "__main__":
    print(is_prime(17))

'''Memoized digit sum calculator'''def sum_digits(n, memo=None):
    """Calculate the sum of the digits of a number, using memoization."""
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n < 10:
        return n
    memo[n] = n % 10 + sum_digits(n // 10, memo)
    return memo[n]

