# A simple descriptor that enforces type checking

class Typed:
    """A descriptor that enforces a value's type on assignment."""

    def __init__(self, expected_type):
        self.expected_type = expected_type

    def __get__(self, instance, owner):
        return instance.__dict__[self.expected_type.__name__]

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(f"Expected {self.expected_type.__name__}, got {type(value).__name__}")
        instance.__dict__[self.expected_type.__name__] = value


class Person:
    """A class that uses a Typed descriptor to enforce types on attributes."""

    name = Typed(str)
    age = Typed(int)

    def __init__(self, name, age):
        self.name = name
        self.age = age

# Example usage
