# lazy_property.py
# A property that computes its value only when accessed for the first time

class Lazy:
    """A descriptor that computes the value lazily."""

    def __init__(self, func):
        self.func = func

    def __get__(self, instance, owner):
        if instance is None:
            return self
        value = self.func(instance)
        setattr(instance, self.func.__name__, value)
        return value

class Data:
    """A class that uses a Lazy descriptor to compute a property on demand."""

    def __init__(self, x):
        self.x = x

    @Lazy
    def square(self):
        print("Computing square...")
        return self.x ** 2

# Example usage
data = Data(5)
print(f"Square: {data.square}")
print(f"Square again: {data.square}")

