# A descriptor that enforces a maximum value for an attribute

class MaxValue:
    """A descriptor that ensures a value does not exceed a given maximum."""

    def __init__(self, max_value):
        self.max_value = max_value

    def __get__(self, instance, owner):
        return instance.__dict__.get(self.max_value, None)

    def __set__(self, instance, value):
        if value > self.max_value:
            raise ValueError(f"Value must be ≤ {self.max_value}")
        instance.__dict__[self.max_value] = value

