# A property that caches the result of an expensive computation

class CachedProperty:
    """A descriptor that caches the result of a property to avoid recomputation."""

    def __init__(self, func):
        self.func = func

    def __get__(self, instance, owner):
        if instance is None:
            return self
        value = self.func(instance)
        setattr(instance, self.func.__name__, value)
        return value

class Expensive:
    """A class that uses a cached property to avoid redundant computations."""

    def __init__(self, x):
        self.x = x

    @CachedProperty
    def square(self):
        print("Computing square...")
        return self.x ** 2

# Example usage
exp = Expensive(5)
print(f"Square: {exp.square}")
print(f"Square again: {exp.square}")

