'''Quicksort implementation with partition function'''

def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

if __name__ == "__main__":
    sample = [3, 6, 8, 10, 1, 2, 1]
    print("Original:", sample)
    print("Sorted:", quicksort(sample))

'''Quicksort with custom comparison function'''

def quicksort(arr, compare):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if compare(x, pivot) < 0]
    middle = [x for x in arr if compare(x, pivot) == 0]
    right = [x for x in arr if compare(x, pivot) > 0]
    return quicksort(left, compare) + middle + quicksort(right, compare)

# Example comparison function for strings

def compare_strings(a, b):
    return len(a) - len(b)

