# Find the longest common prefix among a list of strings

def longest_common_prefix(strings):
    """Return the longest common prefix of the list of strings."""
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

