'''
Demonstrates time vs space tradeoff using memoization for Fibonacci sequence.
'''
import time
def fibonacci(n, cache=None):
    if cache is None:
        cache = {}
    if n in cache:
        return cache[n]
    if n <= 1:
        return n
    cache[n] = fibonacci(n-1, cache) + fibonacci(n-2, cache)
    return cache[n]

def fibonacci_no_cache(n):
    if n <= 1:
        return n
    return fibonacci_no_cache(n-1) + fibonacci_no_cache(n-2)

if __name__ == "__main__":
    n = 35

    start = time.time()
    res = fibonacci_no_cache(n)
    no_cache_time = time.time() - start
    print(f"Without cache: {res} (time: {no_cache_time:.6f}s)")

    start = time.time()
    res = fibonacci(n)
    cache_time = time.time() - start
    print(f"With cache: {res} (time: {cache_time:.6f}s)")

