'''
Compare time and space complexity of bubble sort and quicksort
'''
import time
import random

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

if __name__ == '__main__':
    data = [random.randint(1, 1000) for _ in range(1000)]

    start = time.time()
    sorted_data = bubble_sort(data.copy())
    end = time.time()
    print(f"Bubble Sort: {end - start:.6f} seconds")

    start = time.time()
    sorted_data = quicksort(data.copy())
    end = time.time()
    print(f"Quicksort: {end - start:.6f} seconds")

