import heapq

"""Finds the k largest elements in a list using a min heap. This method is efficient for large data sets."""

def find_k_largest(nums, k):
    """Returns the k largest elements in nums using a min heap."""
    if k <= 0 or k > len(nums):
        return []
    heap = nums[:k]
    heapq.heapify(heap)
    for num in nums[k:]:
        if num > heap[0]:
            heapq.heappushpop(heap, num)
    return sorted(heap, reverse=True)

