"""A task scheduler that uses a priority queue to manage tasks based on priority and execution time."""

class Task:
    def __init__(self, name, priority, duration):
        self.name = name
        self.priority = priority
        self.duration = duration

    def __lt__(self, other):
        return self.priority < other.priority


def task_runner(task):
    print(f"Starting task: {task.name} (Priority: {task.priority}, Duration: {task.duration}s)")
    time.sleep(task.duration)
    print(f"Finished task: {task.name}")


def schedule_tasks(tasks):
    heap = []
    for task in tasks:
        heapq.heappush(heap, task)
    while heap:
        task = heapq.heappop(heap)
        threading.Thread(target=task_runner, args=(task,)).start()

if __name__ == "__main__":
    tasks = [
        Task("Task A", 2, 2),
        Task("Task B", 1, 1),
        Task("Task C", 3, 3)
    ]
    schedule_tasks(tasks)

