'''Sliding window technique to find the longest substring without repeating characters.'''
def longest_unique_substring(s):
    char_index = {}
    max_len = 0
    start = 0
    for end in range(len(s)):
        if s[end] in char_index and char_index[s[end]] >= start:
            start = char_index[s[end]] + 1
        char_index[s[end]] = end
        max_len = max(max_len, end - start + 1)
    return max_len

if __name__ == "__main__":
    s = "abcabcbb"
    print(longest_unique_substring(s))

'''Sliding window technique to count the number of anagrams of a given string in another string.'''
def count_anagrams(s, p):
    from collections import defaultdict
    count = 0
    p_count = defaultdict(int)
    s_count = defaultdict(int)
    for char in p:
        p_count[char] += 1
    window_size = len(p)
    for i in range(len(s)):
        s_count[s[i]] += 1
        if i >= window_size:
            s_count[s[i - window_size]] -= 1
            if s_count[s[i - window_size]] == 0:
                del s_count[s[i - window_size]]
        if s_count == p_count:
            count += 1
    return count

if __name__ == "__main__":
    s = "cbaebabacd"
    p = "abc"
    print(count_anagrams(s, p))

