'''Dijkstra's algorithm with error handling and input validation'''import heapq
def dijkstra_validate(graph, start):
    if not graph or start not in graph:
        raise ValueError("Invalid graph or start node")

    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        dist, node = heapq.heappop(heap)
        if dist > distances[node]:
            continue
        for neighbor, weight in graph[node].items():
            if weight < 0:
                raise ValueError("Negative edge weight not allowed")
            if distances[neighbor] > dist + weight:
                distances[neighbor] = dist + weight
                heapq.heappush(heap, (distances[neighbor], neighbor))
    return distances

