'''Dijkstra's algorithm for finding shortest path between cities'''import heapq
def dijkstra_map(graph, start):
    distances = {city: float('infinity') for city in graph}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        dist, city = heapq.heappop(heap)
        if dist > distances[city]:
            continue
        for neighbor, weight in graph[city].items():
            if distances[neighbor] > dist + weight:
                distances[neighbor] = dist + weight
                heapq.heappush(heap, (distances[neighbor], neighbor))
    return distances

# Example graph: cities and distances between them
graph = {
    'New York': {'Chicago': 790, 'Boston': 290},
    'Chicago': {'New York': 790, 'Denver': 1000, 'St. Louis': 300},
    'Denver': {'Chicago': 1000, 'St. Louis': 800, 'Los Angeles': 1200},
    'St. Louis': {'Chicago': 300, 'Denver': 800},
    'Los Angeles': {'Denver': 1200},
    'Boston': {'New York': 290}
}

if __name__ == '__main__':
    start_city = 'New York'
    result = dijkstra_map(graph, start_city)
    print(f"Shortest distances from {start_city}:")
    for city, dist in result.items():
