# Uses Union-Find to count the number of distinct groups in a list of pairs

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x == root_y:
            return
        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        else:
            self.parent[root_y] = root_x
            if self.rank[root_x] == self.rank[root_y]:
                self.rank[root_x] += 1

def count_groups(pairs):
    max_element = max(max(p) for p in pairs)
    uf = UnionFind(max_element + 1)
    for u, v in pairs:
        uf.union(u, v)
    roots = set()
    for i in range(max_element + 1):
        roots.add(uf.find(i))
    return len(roots)

