'''Dynamic programming solution for the 0/1 knapsack problem.'''

def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(values[i-1] + dp[i-1][w - weights[i-1]], dp[i-1][w])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(f"Maximum value: {knapsack(weights, values, capacity)}")

'''Dynamic programming solution for the unbounded knapsack problem.'''

def unbounded_knapsack(values, weights, capacity):
    n = len(weights)
    dp = [0] * (capacity + 1)

    for w in range(capacity + 1):
        for i in range(n):
            if weights[i] <= w:
                dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

if __name__ == "__main__":
    weights = [1, 3, 4]
    values = [15, 20, 30]
    capacity = 8
    print(f"Maximum value: {unbounded_knapsack(values, weights, capacity)}")

'''Dynamic programming solution for the knapsack problem using memoization.'''

def knapsack_memo(weights, values, capacity):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def helper(index, remaining):
        if index == len(weights) or remaining == 0:
            return 0
        if weights[index] > remaining:
            return helper(index + 1, remaining)
        return max(
            values[index] + helper(index + 1, remaining - weights[index]),
            helper(index + 1, remaining)
        )
    return helper(0, capacity)

if __name__ == "__main__":
    weights = [1, 2, 3]
    values = [6, 10, 12]
    capacity = 5
    print(f"Maximum value: {knapsack_memo(weights, values, capacity)}")

'''Dynamic programming solution for the knapsack problem using a 1D array.'''

def knapsack_1d(weights, values, capacity):
    n = len(weights)
    dp = [0] * (capacity + 1)

    for i in range(n):
        for w in range(capacity, weights[i] - 1, -1):
            dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

if __name__ == "__main__":
    weights = [2, 3, 4]
    values = [3, 4, 5]
    capacity = 5
    print(f"Maximum value: {knapsack_1d(weights, values, capacity)}")

'''Dynamic programming solution for the knapsack problem with multiple constraints.'''

def multi_knapsack(values, weights, capacities):
    n = len(values)
    m = len(capacities)
    dp = [[[0] * (capacities[i] + 1) for _ in range(n)] for i in range(m)]

    for i in range(m):
        for j in range(n):
            for k in range(capacities[i] + 1):
                if weights[j] <= k:
                    dp[i][j][k] = max(dp[i][j-1][k], values[j] + dp[i][j-1][k - weights[j]])
                else:
                    dp[i][j][k] = dp[i][j-1][k]
    return dp[m-1][n-1][capacities[m-1]]

if __name__ == "__main__":
    values = [60, 100, 120]
    weights = [10, 20, 30]
    capacities = [50, 60]
    print(f"Maximum value: {multi_knapsack(values, weights, capacities)}")

