'''Topological sort implementation using Kahn's algorithm'''def topo_sort(graph):
    '''Return a topological sort of the directed graph.\n\n    Args:\n        graph: Dictionary where keys are nodes and values are lists of neighbors.\n\n    Returns:\n        List of nodes in topological order.\n    '''
    in_degree = {node: 0 for node in graph}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1
    queue = [node for node in in_degree if in_degree[node] == 0]
    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if len(result) != len(graph):
        raise ValueError("Graph has a cycle")
    return result

