    if not isinstance(graph, dict):
        raise TypeError("Input must be a dictionary")
    if not graph:
        return []
    in_degree = {node: 0 for node in graph}
    for u in graph:
        if not isinstance(graph[u], list):
            raise ValueError(f"Invalid value for node {u}")
