def cache(func):
    """Decorator that caches function results based on arguments."""
    cache = {}
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            print("Returning cached result")
            return cache[key]
        result = func(*args, **kwargs)
        cache[key] = result
        return result
    return wrapper

@cache
def add(a, b):
    """Returns the sum of two numbers."""
    return a + b

