def type_check(**kwargs):
    """Decorator that enforces type checking on function arguments."""
    def decorator(func):
        def wrapper(*args, **func_kwargs):
            for arg_name, expected_type in kwargs.items():
                if arg_name in func_kwargs:
                    if not isinstance(func_kwargs[arg_name], expected_type):
                        raise TypeError(f"Argument {arg_name} must be of type {expected_type.__name__}")
            return func(*args, **func_kwargs)
        return wrapper
    return decorator

@type_check(a=int, b=int)
