def rate_limit(max_calls):
    """Decorator that limits the number of times a function can be called."""
    def decorator(func):
        func.calls = 0
        def wrapper(*args, **kwargs):
            if func.calls >= max_calls:
                raise Exception(f"Function {func.__name__} has been called too many times")
            func.calls += 1
            return func(*args, **kwargs)
        return wrapper
    return decorator

@rate_limit(2)
def counter():
    """Counts how many times it has been called."""
    print("Function called")

if __name__ == "__main__":
    counter()
    counter()
    counter()

