def quicksort(arr):
    """Sorts a list using the quicksort algorithm.\n\n    Time complexity: O(n log n) average case, O(n²) worst case\n    Space complexity: O(n) due to recursive calls\n    """
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    left = [x for x in arr[1:] if x <= pivot]
    right = [x for x in arr[1:] if x > pivot]
    return quicksort(left) + [pivot] + quicksort(right)

