'''
Stack and Queue classes using Python
'''

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.items:
            raise IndexError("Pop from empty stack")
        return self.items.pop()

    def peek(self):
        if not self.items:
            raise IndexError("Peek from empty stack")
        return self.items[-1]

class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.items:
            raise IndexError("Dequeue from empty queue")
        return self.items.pop(0)

    def peek(self):
        if not self.items:
            raise IndexError("Peek from empty queue")
        return self.items[0]

if __name__ == "__main__":
    s = Stack()
    s.push(10)
    s.push(20)
    print("Stack pop:", s.pop())

    q = Queue()
    q.enqueue(10)
    q.enqueue(20)
    print("Queue dequeue:", q.dequeue())

