import heapq

class Task:
    def __init__(self, name, priority):
        self.name = name
        self.priority = priority

    def __lt__(self, other):
        return self.priority < other.priority

'''A priority queue implementation using heapq with custom Task objects.'''

def main():
    pq = []
    heapq.heappush(pq, Task('Task A', 2))
    heapq.heappush(pq, Task('Task B', 1))
    heapq.heappush(pq, Task('Task C', 3))

    while pq:
        task = heapq.heappop(pq)
        print(f'Processing {task.name} with priority {task.priority}')

if __name__ == '__main__':
    main()

import heapq

def find_k_largest(arr, k):
    '''Return the k largest elements in the list using a min-heap.'''
    if k <= 0 or k > len(arr):
        return []

    heap = arr[:k]
    heapq.heapify(heap)

    for num in arr[k:]:
        if num > heap[0]:
            heapq.heappushpop(heap, num)

    return sorted(heap, reverse=True)

if __name__ == '__main__':
    nums = [3, 2, 1, 5, 6, 4]
    k = 3
    result = find_k_largest(nums, k)
    print(f'The {k} largest numbers are: {result}')

