        def wrapper(*args):
            if len(args) != len(types):
                raise ValueError("Invalid number of arguments")
            for arg, type_ in zip(args, types):
                if not isinstance(arg, type_):
                    raise TypeError(f"Argument {arg} is not of type {type_}")
            return func(*args)
        return wrapper
    return decorator

