def solve_n_queens(n):
    board = [[0 for _ in range(n)] for _ in range(n)]
    solutions = []

    def is_safe(row, col):
        for i in range(row):
            if board[i][col] == 1:
                return False
        for i, j in zip(range(row, -1, -1)), range(col, -1, -1))):
            if board[i][j] == 1:
                return False
        for i, j in zip(range(row, -1, -1), range(col, n))):
            if board[i][j] == 1:
                return False
        return True

    def backtrack(row):
        if row == n:
            solution = ["[" + ", ".join(str(col) for col in row if col == 1) + "]" for row in board]
            solutions.append(solution)
            return
        for col in range(n):
            if is_safe(row, col):
                board[row][col] = 1
                backtrack(row + 1)
                board[row][col] = 0

    backtrack(0)
    return solutions

