'''Dynamic programming with memoization for 0/1 knapsack'''from functools import lru_cachedef knapsack(weights, values, capacity):
    @lru_cache(maxsize=None)
    def helper(index, remaining):
        if index == len(weights) or remaining == 0:
            return 0
        if weights[index] > remaining:
            return helper(index + 1, remaining)
        return max(helper(index + 1, remaining),
                   values[index] + helper(index + 1, remaining - weights[index]))
    return helper(0, capacity)

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(knapsack(weights, values, capacity))

