"""Find the longest common prefix among a list of strings."""

def longest_common_prefix(strs):
    """Return the longest common prefix string among the list of strings."""
    if not strs:
        return ""

    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

if __name__ == "__main__":
    print(longest_common_prefix(["flower","flow","flight"]))

# kmp_matcher.py
"""Implement the Knuth-Morris-Pratt (KMP) algorithm for string matching."""

def compute_lps(pattern):
    """Compute the Longest Prefix Suffix (LPS) array for the pattern."""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def kmp_search(text, pattern):
    """Search for the pattern in the text using the KMP algorithm."""
    if not pattern:
        return 0

    lps = compute_lps(pattern)
    i = 0  # index for text
    j = 0  # index for pattern
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1
            if j == len(pattern):
                return i - j
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return -1

if __name__ == "__main__":
    print(kmp_search("ababcabcab", "abcab"))

