import re

def extract_urls(text):
    """Return a list of URLs found in the given text."""
    url_pattern = r'https?://(?:www\.)?[a-zA-Z0-9-]+(?:\.[a-zA-Z]{2,})+(?:/[a-zA-Z0-9-]*)*'
    return re.findall(url_pattern, text)

if __name__ == "__main__":
    sample_text = "Visit https://example.com or http://test.org for more info."
    print(extract_urls(sample_text))

