    }
    print(dfs(graph, 'A'))

def dfs_paths(graph, start, end, path=None):
    if path is None:
        path = []
    path.append(start)
    if start == end:
        yield path.copy()
    for neighbor in graph[start]:
        if neighbor not in path:
            yield from dfs_paths(graph, neighbor, end, path)
    path.pop()

