def is_bipartite(graph):
    color = {}
    def _dfs(node, c):
        if node in color:
            return color[node] == c
        color[node] = c
        for neighbor in graph[node]:
            if not _dfs(neighbor, 1 - c):
                return False
        return True
    for node in graph:
        if node not in color:
            if not _dfs(node, 0):
                return False
    return True

