# Finds the number of connected components in a graph using BFS
from collections import deque

def count_components(graph):
    visited = set()
    components = 0
    for node in graph:
        if node not in visited:
            components += 1
            queue = deque([node])
            visited.add(node)
            while queue:
                n = queue.popleft()
                for neighbor in graph[n]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
    return components

