    def is_palindrome(self):
        slow = self.head
        fast = self.head
        stack = []
        while fast and fast.next:
            stack.append(slow.data)
            slow = slow.next
            fast = fast.next.next
        if fast:
            slow = slow.next
        while slow:
            if stack.pop() != slow.data:
                return False
            slow = slow.next
        return True

