'''Context manager for a thread lock.'''

import threading

class ThreadLock:
    def __init__(self):
        self.lock = threading.Lock()
    def __enter__(self):
        self.lock.acquire()
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.lock.release()

shared_resource = 0

def increment():
    global shared_resource
    with ThreadLock():
        shared_resource += 1

threads = [threading.Thread(target=increment) for _ in range(10)]
for t in threads:
    t.start()
for t in threads:
    t.join()

print(f'Final value: {shared_resource}')

