# A closure that stores the state of a function

def make_stateful(func):
    state = 0
    def wrapper(*args, **kwargs):
        nonlocal state
        state += 1
        return func(*args, **kwargs)
    return wrapper

@make_stateful
def greet(name):
    return f'Hello, {name}!'

