'''Dynamic Programming implementation of 0/1 Knapsack problem'''def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w - weights[i-1]] + values[i-1])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    weights = [10, 20, 30]
    values = [60, 100, 120]
    capacity = 50
    print(knapsack(weights, values, capacity))

'''Recursive implementation of unbounded knapsack problem'''def unbounded_knapsack(weights, values, capacity):
    if capacity == 0:
        return 0
    max_val = 0
    for i in range(len(weights)):
        if weights[i] <= capacity:
            max_val = max(max_val, values[i] + unbounded_knapsack(weights, values, capacity - weights[i]))
    return max_val

if __name__ == "__main__":
    weights = [1, 3, 4]
    values = [15, 20, 30]
    capacity = 10
    print(unbounded_knapsack(weights, values, capacity))

'''Knapsack problem with memoization using a dictionary'''def knapsack(weights, values, capacity, memo):
    if capacity == 0:
        return 0
    key = (len(weights), capacity)
    if key in memo:
        return memo[key]
    max_val = 0
    for i in range(len(weights)):
        if weights[i] <= capacity:
            max_val = max(max_val, values[i] + knapsack(weights[:i] + weights[i+1:], values[:i] + values[i+1:], capacity - weights[i], memo))
    memo[key] = max_val
    return max_val

if __name__ == "__main__":
    weights = [1, 2, 3]
    values = [10, 15, 40]
    capacity = 4
    memo = {}
    print(knapsack(weights, values, capacity, memo))

