'''
KMP algorithm for efficient string matching.
'''
def build_lps(pattern):
    """Build the Longest Prefix Suffix (LPS) array.""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def kmp_search(text, pattern):
    """Search for pattern in text using KMP algorithm.""
    lps = build_lps(pattern)
    i = 0  # index for text
    j = 0  # index for pattern
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1
        if j == len(pattern):
            print(f'Pattern found at index {i - j}')
            j = lps[j - 1]
        elif i < len(text) and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

def main():
    text = input("Enter text: ")
    pattern = input("Enter pattern: ")
    kmp_search(text, pattern)

if __name__ == "__main__":
    main()

