def k_distinct_substrings(s, k):
    """Count the number of substrings with exactly k distinct characters using sliding window."""
    def at_most_k(k):
        count = 0
        left = 0
        freq = {}
        for right, char in enumerate(s):
            freq[char] = freq.get(char, 0) + 1
            while len(freq) > k:
                freq[s[left]] -= 1
                if freq[s[left]] == 0:
                    del freq[s[left]]
                left += 1
            count += right - left + 1
        return count
    return at_most_k(k) - at_most_k(k - 1)

