    """A decorator that uses wraps to preserve the original function's metadata."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@decorator
def example_function(x):
    """An example function that returns x."""
    return x

if __name__ == "__main__":
    print(example_function.__name__)  # Should print 'example_function'
    print(example_function.__doc__)  # Should print 'An example function that returns x.'

'''Use functools.wraps and lru_cache to create a decorated function with preserved metadata.''

from functools import wraps, lru_cache

def decorator(func):
    """A decorator that uses wraps and lru_cache."""
    @lru_cache(maxsize=None)
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@decorator
def add(a, b):
    """Add two numbers."""
    return a + b

if __name__ == "__main__":
    print(add(2, 3))  # Output: 5
    print(add(2, 3))  # Output: 5 (from cache)
    print(add.__name__)  # Should print 'add'
