'''Stack Demo: Implements a stack using Python lists.'''

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self):
        if not self.is_empty():
            return self.items[-1]
        return None

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

if __name__ == "__main__":
    s = Stack()
    s.push(10)
    s.push(20)
    print(f"Popped: {s.pop()}")
    print(f"Top: {s.peek()}")
    print(f"Size: {s.size()}")

'''Queue Simulation using collections.deque.'''

from collections import deque

class Queue:
    def __init__(self):
        self.items = deque()

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.items.popleft()
        return None

    def peek(self):
        if not self.is_empty():
            return self.items[0]
        return None

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

if __name__ == "__main__":
    q = Queue()
    q.enqueue(1)
    q.enqueue(2)
    print(f"Dequeued: {q.dequeue()}")
    print(f"Front: {q.peek()}")
    print(f"Size: {q.size()}")

