'''Memoized Fibonacci sequence calculator'''
def fibonacci(n, memo={}):
    """Calculate the nth Fibonacci number using memoization."""
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

if __name__ == "__main__":
    print(fibonacci(10))

'''Memoization using a decorator''' from functools import lru_cache

@lru_cache(maxsize=None)
def factorial(n):
    """Calculate factorial of n using memoization."""
    if n == 0:
        return 1
    return n * factorial(n - 1)

if __name__ == "__main__":
    print(factorial(5))

