'''Manual memoization using a dictionary''' def memoize(func):
    """Decorator to memoize function results."""
    memo = {}
    def wrapper(*args):
        if args not in memo:
            memo[args] = func(*args)
        return memo[args]
    return wrapper

@memoize
def multiply(a, b):
    """Multiply two numbers."""
    return a * b

if __name__ == "__main__":
    print(multiply(3, 4))

'''Memoization with a call counter''' from functools import lru_cache

def count_calls(func):
    """Decorator to count function calls."""
    def wrapper(*args, **kwargs):
        wrapper.call_count += 1
        return func(*args, **kwargs)
    wrapper.call_count = 0
    return wrapper

@count_calls
@lru_cache(maxsize=None)
def fibonacci(n):
    """Calculate Fibonacci number with memoization."""
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

if __name__ == "__main__":
    fibonacci(10)
    print(f"Called {fibonacci.call_count} times")

import heapq

def dijkstra(graph, start):
    """Find the shortest path from start to all other nodes in a graph."""
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        current_dist, current_node = heapq.heappop(heap)
        if current_dist > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))
    return distances

