# DFS to find all paths from start to end in a graph

def dfs_paths(graph, start, end, path=None, paths=None):
    if path is None:
        path = [start]
    if paths is None:
        paths = []
    if start == end:
        paths.append(list(path))
        return
    for neighbor in graph[start]:
        if neighbor not in path:
            path.append(neighbor)
            dfs_paths(graph, neighbor, end, path, paths)
            path.pop()

