        'D': ['B', 'C']
    }
    paths = []
    dfs_paths(graph, 'A', 'D', paths=paths)
    print("All paths from A to D:", paths)

# Detect cycles in a graph using DFS

def has_cycle(graph):
    visited = set()
    recursion_stack = set()

    def dfs(node):
        if node in recursion_stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        recursion_stack.remove(node)
        return False

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True
    return False

if __name__ == '__main__':
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': ['B']
    }
    if has_cycle(graph):
        print("Graph contains a cycle.")
    else:
        print("Graph is acyclic.")

