# Find the number of connected components in a graph using DFS

def count_components(graph):
    visited = set()
    components = 0

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)

    for node in graph:
        if node not in visited:
            dfs(node)
            components += 1
    return components

