# Find a path from start to end node using DFS

def dfs_find_path(graph, start, end):
    visited = set()
    path = []

    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        path.append(node)
        if node == end:
            return True
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        path.pop()
        return False

    if dfs(start):
        return path
    return None

