def binary_search(arr, target):
    """Perform binary search on a sorted list and return the index of the target. Returns -1 if not found."

    Args:
        arr (list): A sorted list of elements.
        target: The element to search for.

    Returns:
        int: The index of the target if found, else -1.
    """
    if not isinstance(arr, list):
        raise ValueError("Input must be a list")
    if not arr:
        return -1
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

