def binary_search(arr, target, order='ascending'):
    """Perform binary search on a list with optional order specification."

    Args:
        arr (list): A list of elements.
        target: The element to search for.
        order (str): 'ascending' or 'descending' to specify the list order.

    Returns:
        int: The index of the target if found, else -1.
    """
    if order == 'ascending':
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
    elif order == 'descending':
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] > target:
                left = mid + 1
            else:
                right = mid - 1
    return -1

