def two_pointers_sum(arr, target):

    """Finds pairs in the array that sum to the target using two pointers technique."""

    left = 0
    right = len(arr) - 1
    results = []

    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            results.append((arr[left], arr[right]))
            left += 1
            right -= 1
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return results

if __name__ == "__main__":
    numbers = [1, 2, 3, 4, 5, 6]
    target = 8
    print(f"Pairs that sum to {target}: {two_pointers_sum(numbers, target)}")

def is_palindrome(s):

    """Checks if a string is a palindrome using two pointers."""

    left = 0
    right = len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

if __name__ == "__main__":
    test_str = "racecar"
    print(f"Is '{test_str}' a palindrome? {is_palindrome(test_str)}")

def max_area(heights):

    """Finds the maximum area between two lines using the two pointers technique."""

    left = 0
    right = len(heights) - 1
    max_area = 0

    while left < right:
        current_area = min(heights[left], heights[right]) * (right - left)
        max_area = max(max_area, current_area)
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
    return max_area

if __name__ == "__main__":
    h = [1, 8, 6, 2, 5, 4, 8, 3, 7]
    print(f"Maximum area: {max_area(h)}")

def remove_value(arr, val):

    """Removes all instances of a value from a list using two pointers technique."""

    left = 0
    right = len(arr) - 1

    while left <= right:
        if arr[left] == val:
            arr[left], arr[right] = arr[right], arr[left]
            right -= 1
        else:
            left += 1
    return arr[:right + 1]

if __name__ == "__main__":
    nums = [3, 2, 2, 3]
    val = 3
    print(f"List after removing {val}: {remove_value(nums, val)}")

