import time

def iterative_fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def recursive_fib(n):
    if n <= 1:
        return n
    return recursive_fib(n - 1) + recursive_fib(n - 2)

def compare_fib():
    n = 30

    start = time.time()
    iterative_fib(n)
    iter_time = time.time() - start

    start = time.time()
    recursive_fib(n)
    recur_time = time.time() - start

    print(f'Iterative Fibonacci time: {iter_time:.6f} seconds')
    print(f'Recursive Fibonacci time: {recur_time:.6f} seconds')

if __name__ == "__main__":
    compare_fib()

