import time

def find_duplicates(arr):
    seen = set()
    duplicates = set()
    for num in arr:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)
    return duplicates

def find_duplicates_with_dict(arr):
    seen = {}
    duplicates = {}
    for num in arr:
        if num in seen:
            duplicates[num] = True
        else:
            seen[num] = True
    return list(duplicates.keys())

def compare_duplicates():
    data = [random.randint(1, 100) for _ in range(100000)]

    start = time.time()
    find_duplicates(data)
    set_time = time.time() - start

    start = time.time()
    find_duplicates_with_dict(data)
    dict_time = time.time() - start

    print(f'Set-based time: {set_time:.6f} seconds')
    print(f'Dict-based time: {dict_time:.6f} seconds')

if __name__ == "__main__":
    compare_duplicates()

