'''Binary search implementation in Python'''def binary_search(arr, target):
    '''Perform binary search on a sorted list.'''
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == '__main__':
    sorted_list = [1, 3, 5, 7, 9]
    result = binary_search(sorted_list, 5)
    print(f'Index of 5: {result}')

'''Binary search to find the square root of a number'''def binary_search_sqrt(n):
    '''Approximate the square root of n using binary search.'''
    if n < 0:
        return None
    low, high = 0, n
    while high - low > 1e-7:
        mid = (low + high) / 2
        if mid * mid < n:
            low = mid
        else:
            high = mid
    return round(low, 6)

if __name__ == '__main__':
    number = 25
    result = binary_search_sqrt(number)
    print(f'Square root of {number} is {result}')

