'''Fibonacci with memoization: compares time vs space efficiency.'''

def fibonacci(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

if __name__ == "__main__":
    import time
    n = 35
    start = time.time()
    result = fibonacci(n)
    end = time.time()
    print(f'Fib({n}) = {result}, Time: {end - start:.6f}s')
    print(f'Space: {len(fibonacci.__code__.co_freevars)} variables in memo')

'''Counts word frequencies in a large file, demonstrating time-space tradeoffs.'''

def count_words(filename):
    from collections import defaultdict
    word_counts = defaultdict(int)
    with open(filename, 'r') as f:
        for line in f:
            for word in line.split():
                word_counts[word] += 1
    return word_counts

if __name__ == "__main__":
    import time
    filename = 'large_text.txt'
    start = time.time()
    counts = count_words(filename)
    end = time.time()
    print(f'Counted {len(counts)} unique words in {end - start:.6f}s')

