'''Implements a cache to save computation time for repeated calculations.'''

def expensive_computation(x):
    return x * x

def cached_computation(x, cache):
    if x in cache:
        return cache[x]
    result = expensive_computation(x)
    cache[x] = result
    return result

if __name__ == "__main__":
    import time
    cache = {}

    start = time.time()
    result = cached_computation(10, cache)
    end = time.time()
    print(f'First call: {result}, Time: {end - start:.6f}s')

    start = time.time()
    result = cached_computation(10, cache)
    end = time.time()
    print(f'Second call: {result}, Time: {end - start:.6f}s')

