def find_closest(arr, target):
    """Find the closest value to the target in a sorted list using binary search."""
    left, right = 0, len(arr) - 1
    closest = arr[0]
    while left <= right:
        mid = (left + right) // 2
        if abs(arr[mid] - target) < abs(closest - target):
            closest = arr[mid]
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return closest

