def first_occurrence(arr, target):
    """Find the first occurrence of a target in a sorted list using binary search."""
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            result = mid
