'''Find all anagram substrings in a string using sliding window technique'''def find_anagrams(s, p):
    from collections import defaultdict
    result = []
    count_p = defaultdict(int)
    for ch in p:
        count_p[ch] += 1
    window_size = len(p)
    window_count = defaultdict(int)
    for i in range(len(s)):
        window_count[s[i]] += 1
        if i >= window_size:
            window_count[s[i - window_size]] -= 1
            if window_count[s[i - window_size]] == 0:
                del window_count[s[i - window_size]]
        if window_count == count_p:
            result.append(i - window_size + 1)
    return result

if __name__ == "__main__":
    print(find_anagrams("cbaebabacd", "abc"))

'''Check if all characters in a string are unique using sliding window technique'''def has_unique_chars(s):
    char_set = set()
    left = 0
    for right in range(len(s)):
        while s[right] in char_set:
            char_set.remove(s[left])
            left += 1
        char_set.add(s[right])
    return len(char_set) == len(s)

if __name__ == "__main__":
    print(has_unique_chars("abcdefg"))

'''Count the number of substrings with exactly k distinct characters using sliding window'''def k_distinct_substrings(s, k):
    from collections import defaultdict
    def at_most_k(s, k):
        count = defaultdict(int)
        left = 0
        result = 0
        for right in range(len(s)):
            count[s[right]] += 1
            while len(count) > k:
                count[s[left]] -= 1
                if count[s[left]] == 0:
                    del count[s[left]]
                left += 1
            result += right - left + 1
        return result
    return at_most_k(s, k) - at_most_k(s, k - 1)

if __name__ == "__main__":
    print(k_distinct_substrings("abc", 2))

