            return {"children": {k: _to_dict(v) for k, v in node.children.items()}, "is_end": node.is_end}
        return _to_dict(self.root)
    def save_to_json(self, filename):
        with open(filename, "w") as f:
            json.dump(self.to_dict(), f)
    @staticmethod
    def load_from_json(filename):
        with open(filename, "r") as f:
            data = json.load(f)
        trie = Trie()
        trie.root = TrieNode()
        def _from_dict(node, data):
            for k, v in data["children"].items():
                node.children[k] = TrieNode()
                _from_dict(node.children[k], v)
            node.is_end = data["is_end"]
        _from_dict(trie.root, data)
        return trie
