def can_place(board, row, col):
    for c in range(col):
        if board[row][c] == 1:
            return False
    for r, c in zip(range(row, -1, -1), range(col, -1, -1))):
        if board[r][c] == 1:
            return False
    for r, c in zip(range(row, len(board)), range(col, -1, -1)):
        if board[r][c] == 1:
            return False
    return True

def solve(board, col, n, solutions):
    if col >= n:
        solutions.append([row[:] for row in board])
        return
    for row in range(n):
        if can_place(board, row, col):
            board[row][col] = 1
            solve(board, col + 1, n, solutions)
            board[row][col] = 0

