# Perform DFS on a graph using a recursive approach

from typing import Dict, List

def dfs_recursive(graph: Dict[int, List[int]], start: int, visited: List[int] = None) -> List[int]:
    """Perform DFS using recursion. Returns the list of visited nodes. """
    if visited is None:
        visited = []
    if start not in visited:
        visited.append(start)
        for neighbor in graph[start]:
            dfs_recursive(graph, neighbor, visited)
    return visited

if __name__ == "__main__":
    # Example graph
    graph = {
        1: [2, 3],
        2: [4],
        3: [4],
        4: []
    }
    result = dfs_recursive(graph, 1)
    print("DFS (recursive) traversal:", result)

# dfs_path.py
# Perform DFS and print the path taken

from typing import Dict, List

def dfs_path(graph: Dict[int, List[int]], start: int, target: int) -> List[int]:
    """Perform DFS and return the path from start to target. Returns None if not found. """
    visited = []
    stack = [(start, [start])]

    while stack:
        node, path = stack.pop()
        if node == target:
            return path
        if node not in visited:
            visited.append(node)
            for neighbor in graph[node]:
                stack.append((neighbor, path + [neighbor]))
    return None

if __name__ == "__main__":
    # Example graph
    graph = {
        1: [2, 3],
        2: [4],
        3: [4],
        4: []
    }
    result = dfs_path(graph, 1, 4)
    print("DFS path from 1 to 4:", result)

