    def _hash(self, key):
        return hash(key) % self.size

    def insert(self, key):
        index = self._hash(key)
        for k, v in self.table[index]:
            if k == key:
                self.table[index][self.table[index].index((k, v))] = (k, v + 1))
                return
        self.table[index].append((key, 1))

