    s = "abcabcbb"
    print(f'Longest unique substring: {longest_unique_substring(s)}')

'''Counts the number of anagrams of a string in another string using sliding window.'''
def count_anagrams(s, p):
    from collections import Counter
    p_count = Counter(p)
    s_count = Counter(s[:len(p)])
    count = 0
    for i in range(len(p), len(s)):
        if s_count == p_count:
            count += 1
        s_count[s[i - len(p)]]] -= 1
        if s_count[s[i - len(p)]]] == 0:
            del s_count[s[i - len(p)]]
        s_count[s[i]] = s_count.get(s[i], 0) + 1
    if s_count == p_count:
        count += 1
    return count

if __name__ == "__main__":
    s = "cbaabcc"
    p = "abc"
    print(f'Number of anagrams: {count_anagrams(s, p)}')

