            else:
                self._insert_recursive(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)

    def is_valid_bst(self):
        return self._is_valid_bst_recursive(self.root, float('-inf'), float('inf'))

    def _is_valid_bst_recursive(self, node, min_val, max_val):
        if node is None:
            return True
        if node.value < min_val or node.value > max_val:
            return False
        return (self._is_valid_bst_recursive(node.left, min_val, node.value - 1) and
                self._is_valid_bst_recursive(node.right, node.value + 1, max_val))

