'''
Decorator to cache function results based on arguments.
'''
def cache_decorator(func):
    cache = {}
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            return cache[key]
        result = func(*args, **kwargs)
        cache[key] = result
        return result
    return wrapper

@cache_decorator
def multiply(a, b):
    return a * b

if __name__ == "__main__":
    print(multiply(2, 3))
    print(multiply(2, 3))

'''
Decorator that enforces type checking on function arguments.
'''
def type_check_decorator(func):
    def wrapper(*args, **kwargs):
        for name, value in zip(func.__code__.co_varnames, args):
            if not isinstance(value, func.__annotations__.get(name, type(None))):
                raise TypeError(f"Argument '{name}' must be of type {func.__annotations__.get(name, type(None))}")
        return func(*args, **kwargs)
    return wrapper

@type_check_decorator
def add(a: int, b: int) -> int:
    return a + b

