'''
Depth-First Search that returns the path taken from start to end
'''

def dfs_path(graph, start, end):
    visited = set()
    path = []
    def _dfs(node):
        if node not in visited:
            visited.add(node)
            path.append(node)
            if node == end:
                return True
            for neighbor in graph[node]:
                if _dfs(neighbor):
                    return True
            path.pop()
        return False
    if _dfs(start):
        return path
    return None

