def naive_match(text, pattern):
    """Search for pattern in text using the naive algorithm."""
    n = len(text)
    m = len(pattern)
    matches = []
    for i in range(n - m + 1):
        j = 0
        while j < m and text[i + j] == pattern[j]:
            j += 1
        if j == m:
            matches.append(i)
    return matches

