'''
Read a graph from a file and compute the shortest path using Dijkstra's algorithm.
'''
import heapq
import sys

def load_graph_from_file(filename):
    """Load a graph from a file with one edge per line."
    graph = {}
    with open(filename, 'r') as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) != 3:
                continue
            u, v, w = parts[0], parts[1], float(parts[2])
            if u not in graph:
                graph[u] = {}
            if v not in graph:
                graph[v] = {}
            graph[u][v] = w
            graph[v][u] = w
    return graph

def dijkstra(graph, start):
    """Compute shortest paths from start node."
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        cost, current = heapq.heappop(heap)
        if cost > dist[current]:
            continue
        for neighbor, weight in graph[current].items():
            if dist[neighbor] > cost + weight:
                dist[neighbor] = cost + weight
                heapq.heappush(heap, (dist[neighbor], neighbor))
    return dist

# Main
if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python dijkstra_file.py <filename>")
        sys.exit(1)
    graph = load_graph_from_file(sys.argv[1])
    if not graph:
        print("Invalid graph file")
        sys.exit(1)
    start = next(iter(graph)))
    result = dijkstra(graph, start)
    print(f"Shortest paths from {start}:", result)

