'''Dynamic programming solution for 0/1 knapsack problem''' 

def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], 
                             dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(knapsack(weights, values, capacity))

'''Dynamic programming solution for unbounded knapsack problem''' 

def unbounded_knapsack(weights, values, capacity):
    n = len(weights)
    dp = [0] * (capacity + 1)

    for w in range(capacity + 1):
        for i in range(n):
            if weights[i] <= w:
                dp[w] = max(dp[w], dp[w - weights[i]] + values[i])
    return dp[capacity]

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(unbounded_knapsack(weights, values, capacity))

'''Dynamic programming solution for multi-constrained knapsack problem''' 

def multi_constrained_knapsack(weights, values, capacities):
    n = len(weights)
    m = len(capacities)

    # Initialize a 3D DP array
    dp = [[[0] * (capacities[i] + 1) for i in range(m)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, capacities[0] + 1):
            for j in range(1, capacities[1] + 1):
                if weights[i - 1] <= w and weights[i - 1] <= j:
                    dp[i][w][j] = max(dp[i - 1][w][j], 
                                     dp[i - 1][w - weights[i - 1]][j - weights[i - 1]] + values[i - 1])
                else:
                    dp[i][w][j] = dp[i - 1][w][j]
    return dp[n][capacities[0]][capacities[1]]

if __name__ == "__main__":
    weights = [2, 3]
    values = [3, 4]
    capacities = [5, 5]
    print(multi_constrained_knapsack(weights, values, capacities))

'''Dynamic programming solution for 0/1 knapsack using memoization''' 

def knapsack(weights, values, capacity, memo):
    if (len(weights), capacity) in memo:
        return memo[(len(weights), capacity)]

    if not weights or capacity == 0:
        return 0

    if weights[-1] > capacity:
        result = knapsack(weights[:-1], values[:-1], capacity, memo)
    else:
        result = max(knapsack(weights[:-1], values[:-1], capacity, memo),
                     values[-1] + knapsack(weights[:-1], values[:-1], capacity - weights[-1], memo))

    memo[(len(weights), capacity)] = result
    return result

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    memo = {}
    print(knapsack(weights, values, capacity, memo))

