# Find the number of connected components in a grid using Union-Find

def count_grid_components(grid):
    """Return the number of connected components in a 2D grid."""
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    uf = UnionFind(rows * cols)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                idx = r * cols + c
                if r > 0 and grid[r-1][c] == 1:
                    neighbor_idx = (r-1) * cols + c
                    uf.union(idx, neighbor_idx)
                if c > 0 and grid[r][c-1] == 1:
                    neighbor_idx = r * cols + (c-1)
                    uf.union(idx, neighbor_idx)

    roots = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                idx = r * cols + c
                roots.add(uf.find(idx))
    return len(roots)

