# topological sort implementation

from collections import defaultdict, deque

def topological_sort(graph):
    """Perform topological sort on a directed acyclic graph (DAG).

    Args:
        graph: Dictionary representing the graph, where keys are nodes and values are lists of adjacent nodes.

    Returns:
        List of nodes in topological order.
    """
    in_degree = defaultdict(int)
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = deque([node for node in graph if in_degree[node] == 0])
    result = []

    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result

if __name__ == "__main__":
    # Example usage
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': []
    }
    print("Topological order:", topological_sort(graph))

