# Topological sort using a recursive approach

from collections import defaultdict

def topological_sort_recursive(graph):
    """Perform topological sort on a directed acyclic graph using recursion.

    Args:
        graph: Dictionary representing the graph, where keys are nodes and values are lists of adjacent nodes.

    Returns:
        List of nodes in topological order.
    """
    visited = set()
    result = []

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)
        result.append(node)

    for node in graph:
        if node not in visited:
            dfs(node)

    return result[::-1]  # Reverse to get correct order

