import heapq

class MedianTracker:
    def __init__(self):
        self.min_heap = []  # for upper half
        self.max_heap = []  # for lower half

    def add_number(self, num):
        # Push to max heap (invert value for min heap simulation)
        heapq.heappush(self.max_heap, -num)
        # Push the smallest of the max_heap to the min_heap
        heapq.heappush(self.min_heap, -heapq.heappop(self.max_heap))
        # Balance heaps if needed
        if len(self.min_heap) > len(self.max_heap):
            heapq.heappush(self.max_heap, -heapq.heappop(self.min_heap))

    def get_median(self):
        if len(self.max_heap) == len(self.min_heap):
            return (-self.max_heap[0] + self.min_heap[0]) / 2
        else:
            return -self.max_heap[0]

if __name__ == "__main__":
    tracker = MedianTracker()
    numbers = [1, 3, 5, 2, 4, 6]
    for num in numbers:
        tracker.add_number(num)
        print(f"Current median after {num}: {tracker.get_median()}")

