'''Bubble Sort Implementation with Efficiency Analysis

This script demonstrates the bubble sort algorithm and explains its inefficiency compared to other sorting algorithms.'''

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

