    print("Original:", sample)
    sorted_arr = bubble_sort(sample)
    print("Sorted:", sorted_arr)
    print("\nBubble sort is inefficient for large datasets because it has an O(n^2) time complexity.\nIt performs many unnecessary comparisons and swaps, which makes it slower than more advanced algorithms like quicksort or merge sort.")

