def two_pointers_reverse(s):
    """Reverse a string in place using the two pointers technique."""
    s = list(s)
    left, right = 0, len(s) - 1
    while left < right:
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1
    return ''.join(s)

