        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def merge_sorted(self, other):
        merged = LinkedList()
        current = self.head
        other_current = other.head
        while current and other_current:
            if current.data <= other_current.data:
                merged.append(current.data)
                current = current.next
            else:
                merged.append(other_current.data)
                other_current = other_current.next
        while current:
            merged.append(current.data)
            current = current.next
        while other_current:
            merged.append(other_current.data)
            other_current = other_current.next
        return merged

    def __str__(self):
        elements = []
        current = self.head
        while current:
            elements.append(str(current.data))
            current = current.next
        return ' -> '.join(elements)

