'''Stores last N results to optimize speed at the cost of memory.'''
import time

def compute_square(x):
    time.sleep(0.01)  # Simulate slow computation
    return x * x

class LastNResults:
    def __init__(self, n):
        self.n = n
        self.cache = {}  # {input: result}

    def get(self, x):
        if x in self.cache:
            return self.cache[x]
        result = compute_square(x)
        self.cache[x] = result
        if len(self.cache) > self.n:
            oldest = min(self.cache.keys())
            del self.cache[oldest]
        return result

if __name__ == '__main__':
    cache = LastNResults(3)
    for i in range(10):
        print(f"Square of {i}: {cache.get(i)}")

'''Compares sieve of Eratosthenes and trial division for prime generation.'''
import timeit

def sieve(n):
    sieve = [True] * (n+1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n**0.5)+1):
        if sieve[i]:
            for j in range(i*i, n+1, i):
                sieve[j] = False
    return [i for i, is_prime in enumerate(sieve) if is_prime]

def trial_division(n):
    primes = []
    for i in range(2, n+1):
        is_prime = True
        for j in range(2, int(i**0.5)+1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return primes

if __name__ == '__main__':
    n = 1000
    time_sieve = timeit.timeit(lambda: sieve(n), number=10)
    time_trial = timeit.timeit(lambda: trial_division(n), number=10)
    print(f"Sieve of Eratosthenes time: {time_sieve:.6f} sec")
    print(f"Trial division time: {time_trial:.6f} sec")

