        for r in range(row):
            if board[r] == col or abs(board[r] - col) == row - r:
                return False
        return True

    def backtrack(row):
        nonlocal count
        if row == n:
            count += 1
            return
        for col in range(n):
            if is_safe(col, row):
                board[row] = col
                backtrack(row + 1)
                board[row] = -1

