    """Sorts an array using the bubble sort algorithm.\n\n    Args:\n        arr (list): The unsorted list to be sorted.\n\n    Returns:\n        list: The sorted list.\n    """
    n = len(arr)
    for i in range(n):
        # Last i elements are already in place
        for j in range(0, n-i-1):
            # Swap if the element found is greater than the next element
            if arr[j] > arr[j+1]:
