def quick_sort(arr):
    """Sorts an array using the quick sort algorithm.\n\n    Args:\n        arr (list): The unsorted list to be sorted.\n\n    Returns:\n        list: The sorted list.\n    """
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    left = [x for x in arr[1:] if x < pivot]
    right = [x for x in arr[1:] if x >= pivot]
    return quick_sort(left) + [pivot] + quick_sort(right)

