def binary_search_custom(arr, target, compare_func):
    """Perform binary search with a custom comparison function."""
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        result = compare_func(arr[mid], target)
        if result == 0:
            return mid
        elif result < 0:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    data = [10, 20, 30, 40, 50]
    target = 30
    def compare(a, b):
        return a - b
    result = binary_search_custom(data, target, compare)
    print(f"Found at index: {result}" if result != -1 else "Not found")

def binary_search_first(arr, target):
    """Perform binary search to find the first occurrence of the target in a sorted array."""
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            result = mid
            right = mid - 1  # Continue searching left
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return result

if __name__ == "__main__":
    sorted_list = [1, 2, 2, 3, 4, 4, 5]
    target = 2
    result = binary_search_first(sorted_list, target)
    print(f"First occurrence at index: {result}" if result != -1 else "Not found")

def binary_search_insert(arr, target):
    """Perform binary search to find the insertion point of the target in a sorted list."""
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

if __name__ == "__main__":
    sorted_list = [1, 3, 4, 6, 8]
    target = 5
    result = binary_search_insert(sorted_list, target)
    print(f"Insertion point at index: {result}")

def find_min_rotated(arr):
    """Find the minimum value in a rotated sorted array using binary search."""
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid
    return arr[left]

if __name__ == "__main__":
    rotated_array = [4, 5, 6, 7, 0, 1, 2]
    result = find_min_rotated(rotated_array)
    print(f"Minimum value is: {result}")

