'''
Fibonacci sequence using memoization
'''

def fibonacci(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

if __name__ == "__main__":
    print(fibonacci(10))

'''
Factorial function with memoization
'''

def factorial(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 1
    memo[n] = n * factorial(n - 1, memo)
    return memo[n]

if __name__ == "__main__":
    print(factorial(5))

'''
Power function with memoization
'''

def power(base, exponent, memo=None):
    if memo is None:
        memo = {}
    key = (base, exponent)
    if key in memo:
        return memo[key]
    if exponent == 0:
        return 1
    if exponent < 0:
        return 1 / power(base, -exponent, memo)
    result = base * power(base, exponent - 1, memo)
    memo[key] = result
    return result

if __name__ == "__main__":
    print(power(2, 3))

'''
Sum of list with memoization
'''

def list_sum(lst, memo=None):
    if memo is None:
        memo = {}
    key = tuple(lst)
    if key in memo:
        return memo[key]
    if not lst:
        return 0
    total = lst[0] + list_sum(lst[1:], memo)
    memo[key] = total
    return total

if __name__ == "__main__":
    print(list_sum([1, 2, 3]))

'''
Palindrome checker with memoization
'''

def is_palindrome(s, memo=None):
    if memo is None:
        memo = {}
    if s in memo:
        return memo[s]
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        result = False
    else:
        result = is_palindrome(s[1:-1], memo)
    memo[s] = result
    return result

if __name__ == "__main__":
    print(is_palindrome("radar"))

'''
GCD function with memoization
'''

def gcd(a, b, memo=None):
    if memo is None:
        memo = {}
    key = tuple(sorted((a, b)))
    if key in memo:
        return memo[key]
    if b == 0:
        return a
    result = gcd(b, a % b, memo)
    memo[key] = result
    return result

if __name__ == "__main__":
    print(gcd(48, 18))

